// Cyrus token economy: every tunable number, as admin Settings (`cyrus_tok_*`).
//
// The defaults, types and the pure parser live in ./config-pure (client-safe); this file re-exports them and adds the
// server-only DB read. Import from here on the server, from ./config-pure in client components.
import { parseTokenConfig, type TokenConfig } from "./config-pure";
export * from "./config-pure";

let cache: { cfg: TokenConfig; at: number } | null = null;

/** Server only: the live config (30 s in-process cache; `fresh` bypasses it). */
export async function loadTokenConfig(fresh = false): Promise<TokenConfig> {
  if (!fresh && cache && Date.now() - cache.at < 30_000) return cache.cfg;
  const { getHost } = await import("../host");
  const cfg = parseTokenConfig(await getHost().settings.readStoredPrefix("cyrus_tok_"));
  cache = { cfg, at: Date.now() };
  return cfg;
}

export function clearTokenConfigCache() { cache = null; }
// Cyrus token economy: every tunable number, as admin Settings (`cyrus_tok_*`).
//
// PURE + client-safe (split out of config.ts 2026-10-13 so a client component can import the parser; config.ts re-exports
// everything here and adds `loadTokenConfig`, the DB read).
// Defaults are the recommended numbers from /root/agent-notes/cyrus-economy/ECONOMY.md;
// docs/DOCUMENTATION.md "Cyrus token economy" explains each one. A Setting row overrides
// its default; a blank or unparseable value falls back to the default (never to 0), so
// a fat-fingered admin edit can't silently make builds free or grants huge.
import type { CyrusModelId } from "../models";

export const TOKEN_TIERS = ["free", "katara", "saka", "all"] as const;
export type TokenTier = (typeof TOKEN_TIERS)[number];
export const PLAN_TIERS = ["katara", "saka", "all"] as const;
export type PlanTier = (typeof PLAN_TIERS)[number];
export const isPlanTier = (v: unknown): v is PlanTier => typeof v === "string" && (PLAN_TIERS as readonly string[]).includes(v);

export type Complexity = "simple" | "standard" | "complex";
export type ReserveTable = Record<CyrusModelId, Record<Complexity, [number, number]>>;

export const DEFAULT_RESERVE_TABLE: ReserveTable = {
  katara: { simple: [30, 70], standard: [60, 140], complex: [100, 240] },
  saka: { simple: [35, 100], standard: [60, 220], complex: [110, 400] },
  yakko: { simple: [100, 250], standard: [200, 500], complex: [400, 1000] },
};

export const CYRUS_TOKEN_DEFAULTS = {
  // --- Launch / gate ---
  /** false = only private-preview accounts (lib/preview-access "modbuilder") earn, see or spend tokens. */
  cyrus_tok_live: "false",
  /** true = a build needs tokens and the plan's model unlock. false = tokens are tracked but never block. */
  cyrus_tok_enforce: "true",
  /** Show "Includes N Cyrus tokens" on game checkout (still preview-only until cyrus_tok_live). */
  cyrus_tok_checkout_line: "true",

  // --- What a token is worth ---
  /** Tokens charged per 1 USD of measured AI cost (build service costUsd). 500 = 1 token per $0.002. */
  cyrus_tok_tokens_per_usd: "500",
  cyrus_tok_mult_katara: "1",
  cyrus_tok_mult_saka: "1",
  /** Yakko premium: heavier variance, holds a build slot ~2x longer. */
  cyrus_tok_mult_yakko: "1.25",
  /** Floor for any build that reached the AI. */
  cyrus_tok_min_spend: "5",
  /** Per model x complexity [typical low, high] tokens; high is what a build reserves. JSON. */
  cyrus_tok_reserve_table: JSON.stringify(DEFAULT_RESERVE_TABLE),

  // --- Failure / abuse ---
  cyrus_tok_charge_refused: "true",
  cyrus_tok_charge_cancelled: "true",
  /** % of the actual cost charged for a build that failed on our side (compile, timeout, outage). */
  cyrus_tok_failed_charge_pct: "0",
  /** Our-side failures that are free per rolling window; after that they are charged in full. */
  cyrus_tok_free_failures: "3",
  cyrus_tok_free_failures_days: "7",
  /** Max tokens reserved+spent per rolling 24 h. */
  cyrus_tok_daily_spend_cap: "5000",
  cyrus_tok_new_account_days: "7",
  cyrus_tok_new_account_daily_cap: "1000",
  /** Below this the UI shows the low-balance state. */
  cyrus_tok_low_balance: "100",
  /** One-time starter tokens for an account that has never held any (verified email, economy live). 0 turns it off. */
  cyrus_tok_starter: "70",
  cyrus_tok_starter_days: "30",

  // --- Game-server grants: amount = clamp(round5(base + perUsd * monthly $), min, max) ---
  cyrus_tok_grant_initial_base: "100",
  cyrus_tok_grant_initial_per_usd: "16",
  cyrus_tok_grant_initial_min: "150",
  cyrus_tok_grant_initial_max: "750",
  cyrus_tok_grant_renew_base: "25",
  cyrus_tok_grant_renew_per_usd: "6",
  cyrus_tok_grant_renew_min: "40",
  cyrus_tok_grant_renew_max: "300",
  /** A prepaid N-month term is granted per month, up to this many months. */
  cyrus_tok_grant_term_months_cap: "12",
  /** Server-grant lots expire after this many days (or the term + 30 d, whichever is longer). */
  cyrus_tok_grant_expiry_days: "90",
  /** Initial grants per account per rolling 30 days (farming many cheap servers). */
  cyrus_tok_grant_max_initial_per_30d: "3",
  /** Max unexpired server-grant tokens one account can hold. */
  cyrus_tok_grant_balance_cap: "3000",
  // r41 (PLACEHOLDERS pending owner decision, see TOKEN_PLACEHOLDER_KEYS + OWNER-ACTIONS "r41"):
  /** Which Nxeon servers earn tokens: cyrus_games (games Cyrus builds for) | all_game_servers | all_servers. */
  cyrus_tok_grant_scope: "cyrus_games",
  /** Lifetime tokens one server can ever earn (initial + every renewal). 0 = no per-server cap. */
  cyrus_tok_grant_per_server_cap: "2000",
  /** A server deleted within this many days of its first grant gives back that server's unspent tokens. 0 = never. */
  cyrus_tok_grant_clawback_days: "14",

  // --- Plans (Stripe subscriptions, renew monthly, tokens stack) ---
  cyrus_tok_plan_katara_tokens: "750",
  cyrus_tok_plan_saka_tokens: "3500",
  cyrus_tok_plan_all_tokens: "10000",
  /** Display prices + the proration rate. The real charge is the Stripe Price. */
  cyrus_tok_plan_katara_cents: "499",
  cyrus_tok_plan_saka_cents: "1999",
  cyrus_tok_plan_all_cents: "4999",
  /** r41: while_active = unspent plan tokens roll over month to month for as long as the plan stays active (no age
   *  limit); age = each month's tokens last cyrus_tok_plan_rollover_months (the pre-r41 rule). */
  cyrus_tok_plan_rollover_mode: "while_active",
  /** Rollover cap (r41, PLACEHOLDER): plan tokens held never exceed this many months of the plan's tokens (the excess of
   *  a new month is not credited; nothing already held is taken). 0 = no cap. */
  cyrus_tok_plan_rollover_cap_months: "0",
  /** mode=age only: each month's plan tokens last this many months (so at most this many months stack). */
  cyrus_tok_plan_rollover_months: "3",
  /** r41 (PLACEHOLDER): what happens to plan tokens when the plan ends. freeze_then_expire = kept but not spendable,
   *  back if they resubscribe within the grace, gone after it; grace_then_expire = usable during the grace, then gone;
   *  expire = gone at the period end. */
  cyrus_tok_plan_lapse_rule: "freeze_then_expire",
  /** The lapse grace in days (both grace rules). */
  cyrus_tok_plan_cancel_grace_days: "30",
  /** A failed renewal keeps the unlock this many days past the period end while Stripe retries. */
  cyrus_tok_plan_past_due_grace_days: "3",
  /** Price id overrides; blank = find the price by lookup_key (scripts/cyrus-tokens-stripe-setup.ts). */
  cyrus_tok_price_katara: "",
  cyrus_tok_price_saka: "",
  cyrus_tok_price_all: "",

  // --- One-off top-ups ---
  cyrus_tok_topup_enabled: "true",
  cyrus_tok_topup_tokens_per_usd: "120",
  cyrus_tok_topup_min_cents: "500",
  cyrus_tok_topup_max_cents: "10000",
  cyrus_tok_topup_expiry_days: "365",
  /** true = only accounts with a paid game server or plan may buy a top-up. */
  cyrus_tok_topup_requires_paid: "false",

  // --- Admin ---
  cyrus_tok_admin_grant_expiry_days: "365",
} as const;

export type TokenSettingKey = keyof typeof CYRUS_TOKEN_DEFAULTS;
/** Settings whose default is a placeholder until the owner decides (shown as such in /admin/cyrus-tokens). */
export const TOKEN_PLACEHOLDER_KEYS: readonly TokenSettingKey[] = [
  "cyrus_tok_grant_scope", "cyrus_tok_grant_per_server_cap", "cyrus_tok_grant_clawback_days",
  "cyrus_tok_grant_initial_base", "cyrus_tok_grant_initial_per_usd", "cyrus_tok_grant_initial_min", "cyrus_tok_grant_initial_max",
  "cyrus_tok_grant_renew_base", "cyrus_tok_grant_renew_per_usd", "cyrus_tok_grant_renew_min", "cyrus_tok_grant_renew_max",
  "cyrus_tok_plan_rollover_cap_months", "cyrus_tok_plan_lapse_rule", "cyrus_tok_plan_cancel_grace_days",
];
/** Text settings with a fixed set of values (anything else = the default). */
export const TOKEN_ENUMS = {
  cyrus_tok_grant_scope: ["cyrus_games", "all_game_servers", "all_servers"],
  cyrus_tok_plan_rollover_mode: ["while_active", "age"],
  cyrus_tok_plan_lapse_rule: ["freeze_then_expire", "grace_then_expire", "expire"],
} as const;
export type GrantScope = (typeof TOKEN_ENUMS.cyrus_tok_grant_scope)[number];
export type RolloverMode = (typeof TOKEN_ENUMS.cyrus_tok_plan_rollover_mode)[number];
export type LapseRule = (typeof TOKEN_ENUMS.cyrus_tok_plan_lapse_rule)[number];
export const TOKEN_SETTING_KEYS = Object.keys(CYRUS_TOKEN_DEFAULTS) as TokenSettingKey[];

export type TokenConfig = {
  live: boolean;
  enforce: boolean;
  checkoutLine: boolean;
  tokensPerUsd: number;
  mult: Record<CyrusModelId, number>;
  minSpend: number;
  reserve: ReserveTable;
  chargeRefused: boolean;
  chargeCancelled: boolean;
  failedChargePct: number;
  freeFailures: number;
  freeFailuresDays: number;
  dailyCap: number;
  newAccountDays: number;
  newAccountDailyCap: number;
  lowBalance: number;
  starterTokens: number;
  starterDays: number;
  grant: {
    initial: { base: number; perUsd: number; min: number; max: number };
    renew: { base: number; perUsd: number; min: number; max: number };
    termMonthsCap: number;
    expiryDays: number;
    maxInitialPer30d: number;
    balanceCap: number;
    scope: GrantScope;
    perServerCap: number;
    clawbackDays: number;
  };
  plan: {
    tokens: Record<PlanTier, number>;
    cents: Record<PlanTier, number>;
    rolloverMonths: number;
    rolloverMode: RolloverMode;
    rolloverCapMonths: number;
    lapseRule: LapseRule;
    cancelGraceDays: number;
    pastDueGraceDays: number;
    priceIds: Record<PlanTier, string>;
  };
  topup: { enabled: boolean; tokensPerUsd: number; minCents: number; maxCents: number; expiryDays: number; requiresPaid: boolean };
  adminGrantExpiryDays: number;
};

function num(raw: string | undefined, def: string, { min = 0, max = Number.MAX_SAFE_INTEGER } = {}): number {
  const n = Number(raw);
  const d = Number(def);
  if (raw === undefined || raw.trim() === "" || !Number.isFinite(n)) return d;
  return Math.min(max, Math.max(min, n));
}
function bool(raw: string | undefined, def: string): boolean {
  const v = (raw ?? def).trim().toLowerCase();
  return v === "true" || v === "1" || v === "on";
}

function parseReserve(raw: string | undefined): ReserveTable {
  const out: ReserveTable = JSON.parse(JSON.stringify(DEFAULT_RESERVE_TABLE));
  if (!raw) return out;
  try {
    const j = JSON.parse(raw) as Record<string, Record<string, unknown>>;
    for (const m of Object.keys(out) as CyrusModelId[]) {
      for (const c of ["simple", "standard", "complex"] as Complexity[]) {
        const v = j?.[m]?.[c];
        if (Array.isArray(v) && v.length === 2 && v.every((x) => Number.isFinite(Number(x)) && Number(x) > 0)) {
          const lo = Math.round(Number(v[0]));
          const hi = Math.max(lo, Math.round(Number(v[1])));
          out[m][c] = [lo, hi];
        }
      }
    }
  } catch { /* keep defaults */ }
  return out;
}

/** Pure: stored Setting values (any subset) -> typed config. Unit-tested. */
export function parseTokenConfig(stored: Partial<Record<string, string>>): TokenConfig {
  const D = CYRUS_TOKEN_DEFAULTS;
  const g = (k: TokenSettingKey) => stored[k];
  const n = (k: TokenSettingKey, o?: { min?: number; max?: number }) => num(g(k), D[k], o);
  const b = (k: TokenSettingKey) => bool(g(k), D[k]);
  const e = <K extends keyof typeof TOKEN_ENUMS>(k: K): (typeof TOKEN_ENUMS)[K][number] => {
    const v = (g(k) ?? "").trim();
    return ((TOKEN_ENUMS[k] as readonly string[]).includes(v) ? v : D[k]) as (typeof TOKEN_ENUMS)[K][number];
  };
  return {
    live: b("cyrus_tok_live"),
    enforce: b("cyrus_tok_enforce"),
    checkoutLine: b("cyrus_tok_checkout_line"),
    tokensPerUsd: n("cyrus_tok_tokens_per_usd", { min: 1, max: 100000 }),
    mult: {
      katara: n("cyrus_tok_mult_katara", { min: 0.1, max: 20 }),
      saka: n("cyrus_tok_mult_saka", { min: 0.1, max: 20 }),
      yakko: n("cyrus_tok_mult_yakko", { min: 0.1, max: 20 }),
    },
    minSpend: Math.round(n("cyrus_tok_min_spend", { max: 10000 })),
    reserve: parseReserve(g("cyrus_tok_reserve_table")),
    chargeRefused: b("cyrus_tok_charge_refused"),
    chargeCancelled: b("cyrus_tok_charge_cancelled"),
    failedChargePct: n("cyrus_tok_failed_charge_pct", { max: 100 }),
    freeFailures: Math.round(n("cyrus_tok_free_failures", { max: 1000 })),
    freeFailuresDays: Math.round(n("cyrus_tok_free_failures_days", { min: 1, max: 90 })),
    dailyCap: Math.round(n("cyrus_tok_daily_spend_cap", { min: 1 })),
    newAccountDays: Math.round(n("cyrus_tok_new_account_days", { max: 365 })),
    newAccountDailyCap: Math.round(n("cyrus_tok_new_account_daily_cap", { min: 1 })),
    lowBalance: Math.round(n("cyrus_tok_low_balance")),
    starterTokens: Math.round(n("cyrus_tok_starter", { max: 100000 })),
    starterDays: Math.round(n("cyrus_tok_starter_days", { min: 1, max: 365 })),
    grant: {
      initial: {
        base: n("cyrus_tok_grant_initial_base"), perUsd: n("cyrus_tok_grant_initial_per_usd"),
        min: n("cyrus_tok_grant_initial_min"), max: n("cyrus_tok_grant_initial_max"),
      },
      renew: {
        base: n("cyrus_tok_grant_renew_base"), perUsd: n("cyrus_tok_grant_renew_per_usd"),
        min: n("cyrus_tok_grant_renew_min"), max: n("cyrus_tok_grant_renew_max"),
      },
      termMonthsCap: Math.round(n("cyrus_tok_grant_term_months_cap", { min: 1, max: 36 })),
      expiryDays: Math.round(n("cyrus_tok_grant_expiry_days", { min: 1, max: 3650 })),
      maxInitialPer30d: Math.round(n("cyrus_tok_grant_max_initial_per_30d", { max: 1000 })),
      balanceCap: Math.round(n("cyrus_tok_grant_balance_cap")),
      scope: e("cyrus_tok_grant_scope"),
      perServerCap: Math.round(n("cyrus_tok_grant_per_server_cap")),
      clawbackDays: Math.round(n("cyrus_tok_grant_clawback_days", { max: 365 })),
    },
    plan: {
      tokens: {
        katara: Math.round(n("cyrus_tok_plan_katara_tokens")),
        saka: Math.round(n("cyrus_tok_plan_saka_tokens")),
        all: Math.round(n("cyrus_tok_plan_all_tokens")),
      },
      cents: {
        katara: Math.round(n("cyrus_tok_plan_katara_cents", { min: 1 })),
        saka: Math.round(n("cyrus_tok_plan_saka_cents", { min: 1 })),
        all: Math.round(n("cyrus_tok_plan_all_cents", { min: 1 })),
      },
      rolloverMonths: n("cyrus_tok_plan_rollover_months", { min: 1, max: 120 }),
      rolloverMode: e("cyrus_tok_plan_rollover_mode"),
      rolloverCapMonths: n("cyrus_tok_plan_rollover_cap_months", { max: 120 }),
      lapseRule: e("cyrus_tok_plan_lapse_rule"),
      cancelGraceDays: Math.round(n("cyrus_tok_plan_cancel_grace_days", { max: 3650 })),
      pastDueGraceDays: Math.round(n("cyrus_tok_plan_past_due_grace_days", { max: 60 })),
      priceIds: {
        katara: (g("cyrus_tok_price_katara") ?? "").trim(),
        saka: (g("cyrus_tok_price_saka") ?? "").trim(),
        all: (g("cyrus_tok_price_all") ?? "").trim(),
      },
    },
    topup: {
      enabled: b("cyrus_tok_topup_enabled"),
      tokensPerUsd: n("cyrus_tok_topup_tokens_per_usd", { min: 1 }),
      minCents: Math.round(n("cyrus_tok_topup_min_cents", { min: 50 })),
      maxCents: Math.round(n("cyrus_tok_topup_max_cents", { min: 50, max: 99999999 })),
      expiryDays: Math.round(n("cyrus_tok_topup_expiry_days", { min: 1, max: 3650 })),
      requiresPaid: b("cyrus_tok_topup_requires_paid"),
    },
    adminGrantExpiryDays: Math.round(n("cyrus_tok_admin_grant_expiry_days", { min: 1, max: 3650 })),
  };
}
// Which game servers earn Cyrus tokens: exactly the games Cyrus can build for today, read
// from the Cyrus game registry (lib/cyrus/games.ts, status "live"). Adding a live game there
// makes its servers earn tokens and show the checkout line, with no change here.
// Server game families use the same ids as the registry (minecraft, ark, theisle, palworld,
// rust, valheim); anything else (e.g. "bedrock") earns nothing. Client-safe.
import { CYRUS_GAMES } from "../games";

export function cyrusLiveGameIds(): string[] {
  return CYRUS_GAMES.filter((g) => g.status === "live").map((g) => g.id);
}

export function earnsCyrusTokens(gameFamily: string | null | undefined): boolean {
  return !!gameFamily && cyrusLiveGameIds().includes(gameFamily);
}
// CYRUS SIDE: the plan + token ENTITLEMENT mirrored from Nxeon, the payment provider (Katara / Saka / Yakko plans and
// token packs are Nxeon products). Flag CYRUS_ENTITLEMENT_MIRROR=1 (off = nothing here runs; tierOf reads the plan row
// exactly as before).
//   apply      entitlement.changed (signed webhook, lib/cyrus/bridge/platform-events.ts) or a pulled snapshot: the plan
//              becomes the mirrored CyrusPlan row (stripeSubscriptionId "nxeon:<user>"), older versions are ignored;
//              wallet purchases are credited once by idemKey (the SAME key the direct path uses), refunds/chargebacks
//              take back that lot's unspent tokens (applyPurchaseEvent).
//   read       tierOf -> gateMirroredPlan: a 60 s in-process cache; past it, the mirror must have been CONFIRMED by
//              Nxeon within CYRUS_ENTITLEMENT_MAX_AGE_H (default 36 h), else Cyrus pulls a fresh snapshot through the
//              Platform API; if that fails too the plan counts as unknown = no paid plan (FAIL CLOSED).
//   reconcile  reconcileEntitlements(): re-pull every mirrored user not confirmed in 12 h (worker sweep, daily cadence).
// HOST SEAM: Nxeon is reached only through host.platform.
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import { loadTokenConfig } from "./config";
import { topupTokens } from "./economy";
import { applyPurchaseEvent, purchaseEnvelope } from "./purchase";

type Env = Record<string, string | undefined>;
export const entitlementMirrorEnabled = (env: Env = process.env) => env.CYRUS_ENTITLEMENT_MIRROR === "1";
const maxAgeMs = (env: Env = process.env) => Math.max(1, Math.min(24 * 14, Number(env.CYRUS_ENTITLEMENT_MAX_AGE_H) || 36)) * 3600_000;
export const CACHE_TTL_MS = 60_000;
export const MIRROR_PREFIX = "nxeon:";

/** The wire shape (docs/api/nxeon-platform-v1.openapi.yaml components.schemas.Entitlement). */
export type MirrorEntitlement = {
  subject: string; version: number; issuedAt: string;
  plan: { tier: "katara" | "saka" | "all" | null; status: "active" | "trialing" | "past_due" | "canceled" | "unpaid" | "none"; periodEnd: string | null; cancelAtPeriodEnd: boolean; product: string | null };
  purchases: { idemKey: string; tokens: number | null; cents: number; method: "wallet" | "card"; at: string; refundedCents: number; chargeback: boolean }[];
  partner: { code: string; firstPaymentPct: number; recurringPct: number } | null;
  /** r51 storage add-on wallet charges (optional) */
  storage?: { idemKey: string; gb: number; cents: number; at: string; refundedCents: number }[];
};

const IDEM_RE = /^[A-Za-z0-9:_-]{6,160}$/;
export function parseEntitlement(x: unknown): MirrorEntitlement | null {
  const e = x as MirrorEntitlement;
  if (!e || typeof e !== "object" || typeof e.subject !== "string" || !/^[A-Za-z0-9_:.-]{4,128}$/.test(e.subject) || !Number.isInteger(e.version) || e.version < 0) return null;
  if (!e.plan || !["katara", "saka", "all", null].includes(e.plan.tier) || !["active", "trialing", "past_due", "canceled", "unpaid", "none"].includes(e.plan.status)) return null;
  if (e.plan.periodEnd !== null && Number.isNaN(Date.parse(e.plan.periodEnd))) return null;
  if (!Array.isArray(e.purchases) || e.purchases.length > 1000) return null;
  for (const p of e.purchases) {
    if (!p || !IDEM_RE.test(p.idemKey) || !Number.isInteger(p.cents) || p.cents <= 0 || p.cents > 10_000_000 || !Number.isInteger(p.refundedCents) || p.refundedCents < 0) return null;
    if (p.tokens !== null && (!Number.isInteger(p.tokens) || p.tokens < 0 || p.tokens > 100_000_000)) return null;
    // a purchase must belong to the subject (wallet references embed the user id)
    if (p.idemKey.startsWith("cwt:") && !p.idemKey.startsWith(`cwt:${e.subject}:`)) return null;
  }
  if (e.storage !== undefined) {
    if (!Array.isArray(e.storage) || e.storage.length > 1000) return null;
    for (const s of e.storage) {
      if (!s || typeof s.idemKey !== "string" || !s.idemKey.startsWith(`cst:${e.subject}:g`) || !IDEM_RE.test(s.idemKey) || !Number.isInteger(s.gb) || s.gb < 0 || !Number.isInteger(s.cents) || s.cents < 0 || s.cents > 10_000_000 || !Number.isInteger(s.refundedCents) || s.refundedCents < 0 || Number.isNaN(Date.parse(s.at))) return null;
    }
  }
  return e;
}

const cache = new Map<string, number>();
export function clearEntitlementCacheForTests() { cache.clear(); }

export type ApplyEntitlementResult = { plan: "applied" | "stale" | "confirmed"; credited: number; reversed: number };

/** Idempotent. Older versions never overwrite newer ones (they still CONFIRM the mirror is current). */
export async function applyEntitlement(raw: unknown, now = new Date()): Promise<ApplyEntitlementResult> {
  const e = parseEntitlement(raw);
  if (!e) throw new Error("invalid entitlement");
  const out: ApplyEntitlementResult = { plan: "confirmed", credited: 0, reversed: 0 };
  const cur = await db.cyrusPlan.findUnique({ where: { userId: e.subject } });
  const mirrored = !cur || cur.stripeSubscriptionId.startsWith(MIRROR_PREFIX);
  const curVersion = cur?.lastSyncAt?.getTime() ?? -1;
  if (mirrored && e.version > curVersion) {
    const data = {
      stripeCustomerId: "nxeon", stripeSubscriptionId: `${MIRROR_PREFIX}${e.subject}`,
      tier: e.plan.tier ?? "katara", priceTier: e.plan.tier ?? "katara",
      // a plan-less entitlement is stored as status "none": effectiveTier gives it no paid tier
      status: e.plan.tier ? e.plan.status : "none",
      currentPeriodEnd: e.plan.periodEnd ? new Date(e.plan.periodEnd) : null, cancelAtPeriodEnd: e.plan.cancelAtPeriodEnd,
      endedAt: e.plan.status === "canceled" && e.plan.periodEnd ? new Date(e.plan.periodEnd) : null,
      livemode: true, lastSyncAt: new Date(e.version),
    };
    await db.cyrusPlan.upsert({ where: { userId: e.subject }, create: { userId: e.subject, ...data }, update: data });
    out.plan = "applied";
  } else if (mirrored && cur) {
    // same or older version: touch the row so updatedAt records that Nxeon confirmed it (the freshness rule)
    await db.cyrusPlan.update({ where: { userId: e.subject }, data: { lastSyncAt: cur.lastSyncAt } });
    out.plan = e.version < curVersion ? "stale" : "confirmed";
  } else out.plan = "stale"; // a real (own-Stripe) plan row is never overwritten by the mirror
  const cfg = e.purchases.length ? await loadTokenConfig() : null;
  for (const p of e.purchases) {
    const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: p.idemKey }, select: { id: true } });
    const refunded = p.chargeback ? p.cents : Math.min(p.cents, p.refundedCents);
    const tokens = p.tokens ?? topupTokens(p.cents, cfg!);
    const data = { idemKey: p.idemKey, kind: "topup" as const, method: p.method, tokens, cents: p.cents, expiresAt: new Date(Date.parse(p.at) + cfg!.topup.expiryDays * 86_400_000).toISOString(), note: `Top-up $${(p.cents / 100).toFixed(2)} (${p.method}, from Nxeon)` };
    if (!row) {
      // fully refunded before it was ever credited (e.g. the compensating refund) -> nothing to credit
      if (refunded >= p.cents) continue;
      const r = await applyPurchaseEvent(purchaseEnvelope("purchase.completed", e.subject, data, now));
      if (r.applied) out.credited += r.tokens;
    }
    // a refund already taken back on this side (refundWalletTopup, a Stripe refund) is not taken twice
    const priorRevoke = row ? await db.cyrusTokenLedger.findFirst({ where: { kind: "revoke", sourceRef: row.id }, select: { id: true } }) : null;
    if (refunded > 0 && !priorRevoke && (row || !(refunded >= p.cents))) {
      const r = await applyPurchaseEvent(purchaseEnvelope("purchase.refunded", e.subject, { ...data, refundedCents: refunded }, now));
      if (r.applied) out.reversed += r.tokens;
    }
  }
  // r51: storage add-on charges the mirror has not applied yet (lost apply, dead webhook): once, by idemKey
  if (e.storage?.length) {
    const { applyMirroredStorageCharge } = await import("../storage/addon");
    for (const s of e.storage) await applyMirroredStorageCharge(e.subject, s, now);
  }
  cache.set(e.subject, now.getTime());
  return out;
}

/** Pull one user's snapshot from Nxeon and apply it. false when there is no Platform API or it failed. */
export async function pullEntitlement(userId: string, now = new Date()): Promise<boolean> {
  const p = getHost().platform;
  if (!p) return false;
  try { await applyEntitlement(await p.as(userId).entitlements(), now); return true; }
  catch (e) { console.error("[cyrus-entitlement] pull failed", userId, (e as Error).message); return false; }
}

/** The fail-closed read rule tierOf applies to the plan row while the mirror is on. */
export async function gateMirroredPlan<P extends { stripeSubscriptionId: string; updatedAt: Date } | null>(userId: string, plan: P, env: Env = process.env, now = new Date()): Promise<P | null> {
  if (!entitlementMirrorEnabled(env)) return plan;
  // a plan this app bills itself (own Stripe, or Cyrus still inside Nxeon) is authoritative here: never gated
  if (plan && !plan.stripeSubscriptionId.startsWith(MIRROR_PREFIX)) return plan;
  const t = now.getTime();
  const hit = cache.get(userId);
  if (hit !== undefined && t - hit < CACHE_TTL_MS) return plan;
  if (plan && t - plan.updatedAt.getTime() < maxAgeMs(env)) { cache.set(userId, t); return plan; }
  // unknown or stale: one pull; failure = no paid plan
  if (await pullEntitlement(userId, now)) {
    const fresh = await db.cyrusPlan.findUnique({ where: { userId } });
    return (fresh && fresh.stripeSubscriptionId.startsWith(MIRROR_PREFIX) ? fresh : null) as P | null;
  }
  return null;
}

/** Reconciliation (worker, flag on): re-pull every mirrored user not confirmed within 12 h. */
export async function reconcileEntitlements(o: { limit?: number; now?: Date } = {}, env: Env = process.env): Promise<{ checked: number; pulled: number; failed: number }> {
  if (!entitlementMirrorEnabled(env) || !getHost().platform) return { checked: 0, pulled: 0, failed: 0 };
  const now = o.now ?? new Date();
  const rows = await db.cyrusPlan.findMany({ where: { stripeSubscriptionId: { startsWith: MIRROR_PREFIX }, updatedAt: { lt: new Date(now.getTime() - 12 * 3600_000) } }, select: { userId: true }, take: o.limit ?? 200, orderBy: { updatedAt: "asc" } });
  let pulled = 0, failed = 0;
  for (const r of rows) if (await pullEntitlement(r.userId, now)) pulled++; else failed++;
  return { checked: rows.length, pulled, failed };
}

// Cyrus token economy: the pure rules (no DB, no clock unless passed in, no network).
// Unit-tested in test/cyrus-tokens-economy.test.ts. Client-safe.
import { estimate } from "../estimate";
import type { CyrusModelId } from "../models";
import type { Complexity, PlanTier, TokenConfig, TokenTier } from "./config";

const DAY = 86_400_000;
export const round5 = (n: number) => Math.round(n / 5) * 5;
const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

// ---------------------------------------------------------------------------
// Models per tier
// ---------------------------------------------------------------------------

export const TIER_RANK: Record<TokenTier, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const TIER_MODELS: Record<TokenTier, CyrusModelId[]> = {
  free: ["katara"],
  katara: ["katara"],
  saka: ["katara", "saka"],
  all: ["katara", "saka", "yakko"],
};
export const TIER_LABEL: Record<TokenTier, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

export const modelsFor = (tier: TokenTier) => TIER_MODELS[tier];
export const canUseModel = (tier: TokenTier, model: CyrusModelId) => TIER_MODELS[tier].includes(model);
/** The cheapest tier that unlocks a model. */
export const tierForModel = (model: CyrusModelId): PlanTier => (model === "yakko" ? "all" : model === "saka" ? "saka" : "katara");
export const maxTier = (a: TokenTier, b: TokenTier): TokenTier => (TIER_RANK[a] >= TIER_RANK[b] ? a : b);
/** Best model a tier may use by default when the request names none. */
export const defaultModelFor = (tier: TokenTier): CyrusModelId => (canUseModel(tier, "saka") ? "saka" : "katara");

export type PlanState = {
  tier: string;
  status: string;
  currentPeriodEnd: Date | null;
  endedAt?: Date | null;
} | null;

/**
 * The account's model entitlement right now. A plan entitles its PAID tier while the paid
 * period runs (also after cancel, until the period ends), plus `pastDueGraceDays` while
 * Stripe retries a failed renewal. An admin override can only raise it.
 */
export function effectiveTier(input: { plan: PlanState; override?: string | null; overrideUntil?: Date | null; now: Date; cfg: TokenConfig }): TokenTier {
  const { plan, now, cfg } = input;
  let tier: TokenTier = "free";
  if (plan && (plan.tier === "katara" || plan.tier === "saka" || plan.tier === "all") && plan.currentPeriodEnd) {
    const end = plan.currentPeriodEnd.getTime();
    const ok =
      ["active", "trialing"].includes(plan.status) ? now.getTime() < end + DAY // a day of slack for webhook lag
      : plan.status === "past_due" ? now.getTime() < end + cfg.plan.pastDueGraceDays * DAY
      : plan.status === "canceled" ? now.getTime() < end
      : false; // incomplete, incomplete_expired, unpaid, paused
    if (ok) tier = plan.tier;
  }
  const o = input.override;
  if ((o === "katara" || o === "saka" || o === "all") && (!input.overrideUntil || input.overrideUntil.getTime() > now.getTime())) tier = maxTier(tier, o);
  return tier;
}

// ---------------------------------------------------------------------------
// Game-server grants
// ---------------------------------------------------------------------------

function perMonth(kind: "initial" | "renew", monthlyCents: number, cfg: TokenConfig): number {
  if (!(monthlyCents > 0)) return 0;
  const r = cfg.grant[kind];
  return Math.round(clamp(round5(r.base + r.perUsd * (monthlyCents / 100)), r.min, r.max));
}

export type ServerGrant = { tokens: number; initialPerMonth: number; renewPerMonth: number; months: number; expiresInDays: number };

/**
 * Tokens for a game-server purchase ("initial") or a paid renewal ("renewal").
 * `monthlyCents` = what the customer actually pays per month (after discounts, before tax).
 * A prepaid N-month term earns the per-month renewal amount for each extra month, capped.
 */
export function serverGrant(kind: "initial" | "renewal", monthlyCents: number, termMonths: number, cfg: TokenConfig): ServerGrant {
  const months = clamp(Math.round(termMonths || 1), 1, cfg.grant.termMonthsCap);
  const ini = perMonth("initial", monthlyCents, cfg);
  const ren = perMonth("renew", monthlyCents, cfg);
  const tokens = kind === "initial" ? (ini ? ini + ren * (months - 1) : 0) : ren * months;
  const expiresInDays = Math.max(cfg.grant.expiryDays, Math.round(termMonths || 1) * 31 + 30);
  return { tokens, initialPerMonth: ini, renewPerMonth: ren, months, expiresInDays };
}

/** The checkout line: "Includes N Cyrus tokens (+M every renewal)". */
export function checkoutLine(monthlyCents: number, termMonths: number, cfg: TokenConfig): { initial: number; renewal: number; text: string } | null {
  const i = serverGrant("initial", monthlyCents, termMonths, cfg);
  const r = serverGrant("renewal", monthlyCents, termMonths, cfg);
  if (!i.tokens) return null;
  return { initial: i.tokens, renewal: r.tokens, text: `Includes ${fmt(i.tokens)} Cyrus tokens (+${fmt(r.tokens)} every renewal) · Beta, Minecraft Java` };
}

export const fmt = (n: number) => Math.round(n).toLocaleString("en-US");

// ---------------------------------------------------------------------------
// Builds: estimate, reserve, settle
// ---------------------------------------------------------------------------

export function complexityOf(text: string): Complexity {
  return estimate(text, "saka").complexity;
}

export function reserveRange(model: CyrusModelId, complexity: Complexity, cfg: TokenConfig): [number, number] {
  return cfg.reserve[model]?.[complexity] ?? cfg.reserve.saka.standard;
}

/**
 * Live-test fix (C1): what a build HOLDS. The reserve table's range, raised to the planned estimate in tokens
 * (lib/cyrus/planner/estimate.ts, +20% headroom on the high end) so the real spend rarely exceeds the hold: the first
 * live Yakko build held 250 (the table's simple high) and spent 431. Without an estimate: the table, unchanged.
 */
export function holdRange(model: CyrusModelId, complexity: Complexity, cfg: TokenConfig, usd?: readonly [number, number]): [number, number] {
  const t = reserveRange(model, complexity, cfg);
  if (!usd) return t;
  const lo = tokensForCost(usd[0], model, cfg);
  const hi = Math.ceil(tokensForCost(usd[1], model, cfg) * 1.2);
  return [Math.max(t[0], lo), Math.max(t[1], hi, lo)];
}

/** Pre-build estimate shown in the composer: the [typical, high] token range. */
export function estimateTokens(text: string, model: CyrusModelId, cfg: TokenConfig): { complexity: Complexity; low: number; high: number } {
  const complexity = complexityOf(text);
  const [low, high] = reserveRange(model, complexity, cfg);
  return { complexity, low, high };
}

/**
 * How much to hold for a build: the high end of the range, or everything the account has
 * when that is less but still covers the typical cost. null = not enough to start.
 */
export function reserveAmount(available: number, range: [number, number]): number | null {
  if (available >= range[1]) return range[1];
  if (available >= range[0]) return available;
  return null;
}

/** Real AI cost -> tokens. 0 when nothing reached the AI. */
export function tokensForCost(costUsd: number, model: CyrusModelId, cfg: TokenConfig): number {
  if (!(costUsd > 0)) return 0;
  return Math.max(cfg.minSpend, Math.ceil(costUsd * cfg.tokensPerUsd * (cfg.mult[model] ?? 1) - 1e-9));
}

export type SettleInput = { status: string; errorCode: string | null; costUsd: number; model: CyrusModelId; freeFailuresUsed: number };
export type SettleDecision = { charge: number; reason: "succeeded" | "refused" | "cancelled" | "failed_free" | "failed_partial" | "failed_over_limit" };

/** What a finished build costs. The charge is NOT capped at the reserve; the ledger caps it at the balance. */
export function settleCharge(i: SettleInput, cfg: TokenConfig): SettleDecision {
  const full = tokensForCost(i.costUsd, i.model, cfg);
  if (i.status === "succeeded") return { charge: full, reason: "succeeded" };
  if (i.errorCode === "refused") return { charge: cfg.chargeRefused ? full : 0, reason: "refused" };
  if (i.errorCode === "cancelled") return { charge: cfg.chargeCancelled ? full : 0, reason: "cancelled" };
  if (i.freeFailuresUsed >= cfg.freeFailures) return { charge: full, reason: "failed_over_limit" };
  const part = Math.ceil((full * cfg.failedChargePct) / 100);
  return part > 0 ? { charge: part, reason: "failed_partial" } : { charge: 0, reason: "failed_free" };
}

export function dailyCapFor(accountCreatedAt: Date, now: Date, cfg: TokenConfig): number {
  return now.getTime() - accountCreatedAt.getTime() < cfg.newAccountDays * DAY ? Math.min(cfg.newAccountDailyCap, cfg.dailyCap) : cfg.dailyCap;
}

// ---------------------------------------------------------------------------
// Plans
// ---------------------------------------------------------------------------

/**
 * Tokens for one paid plan invoice.
 *  - subscription_create / subscription_cycle: the tier's full monthly amount (they stack).
 *  - subscription_update (an upgrade's proration): tokens in proportion to the money collected,
 *    at the new tier's rate, never more than one month of the new tier.
 */
export function planInvoiceTokens(i: { billingReason: string | null; amountPaidCents: number; tier: PlanTier; priceCents?: number | null }, cfg: TokenConfig): number {
  if (!(i.amountPaidCents > 0)) return 0;
  const monthly = cfg.plan.tokens[i.tier];
  if (i.billingReason === "subscription_create" || i.billingReason === "subscription_cycle") return monthly;
  // The proration rate is the plan's REAL Stripe price when known (the Setting is the fallback).
  const price = i.priceCents && i.priceCents > 0 ? i.priceCents : cfg.plan.cents[i.tier];
  if (i.billingReason === "subscription_update") return Math.min(monthly, Math.round((i.amountPaidCents / price) * monthly));
  return 0;
}

/** A plan month's tokens expire `rolloverMonths` months (31-day months) after they were granted. */
export function planLotExpiry(grantedAt: Date, cfg: TokenConfig): Date {
  return new Date(grantedAt.getTime() + Math.round(cfg.plan.rolloverMonths * 31) * DAY);
}

export function topupTokens(cents: number, cfg: TokenConfig): number {
  return Math.floor((cents / 100) * cfg.topup.tokensPerUsd);
}

export function validTopupCents(cents: number, cfg: TokenConfig): boolean {
  return Number.isInteger(cents) && cents >= cfg.topup.minCents && cents <= cfg.topup.maxCents;
}

/** Plan tier of a Stripe price lookup key: cyrus_plan_<tier>_v1. */
export const PLAN_LOOKUP_KEY = (tier: PlanTier) => `cyrus_plan_${tier}_v1`;
export function tierFromLookupKey(k: string | null | undefined): PlanTier | null {
  const m = /^cyrus_plan_(katara|saka|all)_v\d+$/.exec(k || "");
  return m ? (m[1] as PlanTier) : null;
}

/** Recommended worst-case margin per plan (all tokens burnt at multiplier 1, Stripe 2.9% + 30c). */
export function planMargin(tier: PlanTier, cfg: TokenConfig): { priceUsd: number; aiCostUsd: number; stripeFeeUsd: number; marginUsd: number; marginPct: number } {
  const priceUsd = cfg.plan.cents[tier] / 100;
  const aiCostUsd = cfg.plan.tokens[tier] / cfg.tokensPerUsd;
  const stripeFeeUsd = priceUsd * 0.029 + 0.3;
  const marginUsd = priceUsd - aiCostUsd - stripeFeeUsd;
  return { priceUsd, aiCostUsd, stripeFeeUsd, marginUsd, marginPct: priceUsd ? marginUsd / priceUsd : 0 };
}
