60	const num = (v: string | undefined, d: string, min: number, max: number, int = true): number => {
61	  const n = Number(v);
62	  if (v === undefined || v.trim() === "" || !Number.isFinite(n) || n < min || n > max || (int && !Number.isInteger(n))) return Number(d);
63	  return n;
64	};
