66	export function parseStorageConfig(stored: Record<string, string | undefined> = {}): StorageConfig {
67	  const D = STORAGE_DEFAULTS;
68	  const g = (k: StorageSettingKey, min: number, max: number, int = true) => num(stored[k], D[k], min, max, int);
69	  const t = validatePriceTable(stored.cyrus_storage_price_table ?? "");
70	  const rule = (PRICING_RULES as readonly string[]).includes(stored.cyrus_storage_pricing_rule ?? "") ? (stored.cyrus_storage_pricing_rule as PricingRule) : (D.cyrus_storage_pricing_rule as PricingRule);
71	  const w = String(stored.cyrus_storage_warn_pcts ?? "").split(",").map((x) => Number(x.trim()));
72	  const warnOk = w.length === 3 && w.every((x) => Number.isInteger(x) && x >= 1 && x <= 100) && w[0] < w[1] && w[1] < w[2];
73	  const warnPcts = (warnOk ? w : D.cyrus_storage_warn_pcts.split(",").map(Number)) as [number, number, number];
74	  const warn = g("cyrus_storage_pool_warn_pct", 1, 99), crit = g("cyrus_storage_pool_crit_pct", 1, 100);
75	  return {
76	    quotaGb: {
77	      free: g("cyrus_storage_quota_free_gb", 0, 10_000, false),
78	      katara: g("cyrus_storage_quota_katara_gb", 0, 10_000, false),
79	      saka: g("cyrus_storage_quota_saka_gb", 0, 10_000, false),
80	      all: g("cyrus_storage_quota_all_gb", 0, 10_000, false),
81	    },
82	    table: t.ok ? t.table : DEFAULT_PRICE_TABLE,
83	    rule,
84	    addonMaxGb: g("cyrus_storage_addon_max_gb", 1, 100_000),
85	    graceDays: g("cyrus_storage_grace_days", 0, 365),
86	    warnPcts,
87	    retentionDays: g("cyrus_storage_retention_days", 1, 3650),
88	    diskCostUsdPerGbMonth: g("cyrus_storage_disk_cost_usd_gb_month", 0, 100, false),
89	    poolWarnPct: warn < crit ? warn : Number(D.cyrus_storage_pool_warn_pct),
90	    poolCritPct: warn < crit ? crit : Number(D.cyrus_storage_pool_crit_pct),
91	  };
92	}
