97	export type MeterLevel = "ok" | "warn" | "high" | "full";
98	/** ok < warn% <= warn < high% <= high < full% <= full. Quota 0 with any usage = full. */
99	export function meterLevel(usedBytes: number, quota: number, cfg: Pick<StorageConfig, "warnPcts">): { level: MeterLevel; pct: number } {
100	  if (quota <= 0) return { level: usedBytes > 0 ? "full" : "ok", pct: usedBytes > 0 ? 100 : 0 };
101	  const pct = (usedBytes / quota) * 100;
102	  const [w, h, f] = cfg.warnPcts;
103	  return { level: pct >= f ? "full" : pct >= h ? "high" : pct >= w ? "warn" : "ok", pct: Math.round(pct * 10) / 10 };
104	}
