115	// Cyrus storage accounting (r51). PURE + client-safe: what counts, dedupe, per-mod / per-game rollups, the over-quota
116	// state machine and the write decision. The collector (./collect.ts) turns rows and files into StorageItems; the
117	// service (./service.ts) stores the result.
118	//
119	// WHAT COUNTS (one account):
120	//   builds     each stored build jar (ModBuild.jarPath set: jarSize, content key jarSha256)
121	//   assets     project assets (CyrusProjectAsset: size, key sha256), textures, sounds, models, designs, configs
122	//   revisions  each revision's spec + manifest + engine record as stored (Postgres column sizes)
123	//   packs      each Mod Pack version archive (.nxpack zip) + each build's hosted resource pack and data packs (result.assets)
124	//   drafts     autosaved studio drafts (CyrusModelDraft doc size)
125	//   uploads    reference images: pending uploads and the copies attached to builds
126	//   library    library contributions you own that are not removed (catalog entry bytes, key sha256)
127	// DEDUPE: content-addressed bytes (same sha256) count ONCE per account, under the first category in CATEGORY_ORDER that
128	// holds them. Rows without a content hash (revisions, drafts, uploads) count per row. Per mod and per game a file counts
129	// once inside that mod / game, so a file two mods share shows in both mods, while the account total counts it once.
130	// Never counted: the shared asset library itself, other creators' content, installs on servers (they live on the server).
131	export const CATEGORY_ORDER = ["builds", "assets", "packs", "revisions", "drafts", "uploads", "library"] as const;
132	export type StorageCategory = (typeof CATEGORY_ORDER)[number];
133	export const CATEGORY_LABEL: Record<StorageCategory, string> = {
134	  builds: "Builds (jars)",
135	  assets: "Assets (textures, sounds, models, designs)",
136	  packs: "Packs (resource, data and Mod Packs)",
137	  revisions: "Revisions and specs",
138	  drafts: "Studio drafts",
139	  uploads: "Uploads and reference images",
140	  library: "Library contributions you own",
141	};
