143	export type StorageItem = {
144	  /** "sha256:<hex>" for content-addressed bytes, "row:<kind>:<id>" otherwise */
145	  key: string;
146	  bytes: number;
147	  category: StorageCategory;
148	  /** the mod (ModBuild chain root, or "p:<projectId>" for a project with no build) */
149	  modId: string | null;
150	  game: string | null;
151	  label?: string | null;
152	  at?: string | null;
153	};
154	
155	export type ModRollup = { modId: string; game: string | null; label: string | null; bytes: number; byCategory: Partial<Record<StorageCategory, number>>; items: number };
156	export type StorageBreakdown = {
157	  totalBytes: number;
158	  /** before dedupe */
159	  rawBytes: number;
160	  dedupedBytes: number;
161	  items: number;
162	  byCategory: Record<StorageCategory, number>;
163	  byGame: Record<string, number>;
164	  byMod: ModRollup[];
165	  modsTruncated: number;
166	};
167	
168	export const MAX_MODS_STORED = 200;
169	const rank = (c: StorageCategory) => CATEGORY_ORDER.indexOf(c);
170	const clean = (n: number) => (Number.isFinite(n) && n > 0 ? Math.floor(n) : 0);
171	
172	export function rollup(items: StorageItem[]): StorageBreakdown {
173	  const byKey = new Map<string, StorageItem>();
174	  let raw = 0;
175	  for (const it of items) {
176	    const b = clean(it.bytes);
177	    raw += b;
178	    const cur = byKey.get(it.key);
179	    if (!cur || rank(it.category) < rank(cur.category)) byKey.set(it.key, { ...it, bytes: Math.max(b, cur?.bytes ?? 0) });
180	    else if (b > cur.bytes) cur.bytes = b;
181	  }
182	  const byCategory = Object.fromEntries(CATEGORY_ORDER.map((c) => [c, 0])) as Record<StorageCategory, number>;
183	  let total = 0;
184	  for (const it of byKey.values()) { byCategory[it.category] += it.bytes; total += it.bytes; }
185	
186	  const mods = new Map<string, { r: ModRollup; keys: Set<string> }>();
187	  const games = new Map<string, Set<string>>();
188	  const gameBytes: Record<string, number> = {};
189	  for (const it of items) {
190	    const b = clean(it.bytes);
191	    const g = it.game ?? "unassigned";
192	    const gs = games.get(g) ?? new Set<string>();
193	    if (!gs.has(it.key)) { gs.add(it.key); gameBytes[g] = (gameBytes[g] ?? 0) + b; }
194	    games.set(g, gs);
195	    if (!it.modId) continue;
196	    const m = mods.get(it.modId) ?? { r: { modId: it.modId, game: it.game, label: it.label ?? null, bytes: 0, byCategory: {}, items: 0 }, keys: new Set<string>() };
197	    if (!m.r.label && it.label) m.r.label = it.label;
198	    if (!m.keys.has(it.key)) {
199	      m.keys.add(it.key);
200	      m.r.bytes += b; m.r.items++;
201	      m.r.byCategory[it.category] = (m.r.byCategory[it.category] ?? 0) + b;
202	    }
203	    mods.set(it.modId, m);
204	  }
205	  const all = [...mods.values()].map((m) => m.r).sort((a, b) => b.bytes - a.bytes || a.modId.localeCompare(b.modId));
206	  return { totalBytes: total, rawBytes: raw, dedupedBytes: raw - total, items: byKey.size, byCategory, byGame: gameBytes, byMod: all.slice(0, MAX_MODS_STORED), modsTruncated: Math.max(0, all.length - MAX_MODS_STORED) };
207	}
