210	// Over quota: grace after a quota DROP, read-only for new writes after it. Nothing is ever deleted automatically.
211	// ---------------------------------------------------------------------------
212	
213	export type OverState = { overSince: Date | null; graceUntil: Date | null };
214	
215	/** Called on every recompute. Grace starts when usage is over a quota that went DOWN since the last recompute
216	 *  (downgrade, cancel, refund, failed renewal, plan lapse) or on the account's first measurement (launch day); going over
217	 *  by your own new writes has no grace (the write gate refuses them first; only a build's own output can cross). */
218	export function nextOverState(a: { usedBytes: number; quotaBytes: number; prevQuotaBytes: number | null; prev: OverState | null; graceDays: number; now: Date }): OverState {
219	  if (a.usedBytes <= a.quotaBytes) return { overSince: null, graceUntil: null };
220	  const overSince = a.prev?.overSince ?? a.now;
221	  if (a.prev?.graceUntil) return { overSince, graceUntil: a.prev.graceUntil };
222	  const dropped = a.prevQuotaBytes === null || a.quotaBytes < a.prevQuotaBytes;
223	  return { overSince, graceUntil: dropped && a.graceDays > 0 ? new Date(a.now.getTime() + a.graceDays * 86_400_000) : null };
224	}
225	
226	export type WriteKind = "build" | "upload" | "asset" | "library" | "pack" | "import";
227	export type WriteDecision = { ok: true; grace: boolean } | { ok: false; code: "storage_full" | "storage_unknown"; usedBytes: number; quotaBytes: number };
228	
229	/** The ONE rule: a write of `addBytes` (0 = unknown size, e.g. a build) is allowed while used + pending + add stays within
230	 *  the quota (a build needs room left), or while a grace period runs. */
231	export function storageWriteDecision(a: { usedBytes: number; pendingBytes: number; quotaBytes: number; addBytes: number; graceUntil: Date | null; now: Date }): WriteDecision {
232	  const total = a.usedBytes + a.pendingBytes;
233	  const fits = a.addBytes > 0 ? total + a.addBytes <= a.quotaBytes : total < a.quotaBytes;
234	  if (fits) return { ok: true, grace: false };
235	  if (a.graceUntil && a.now.getTime() < a.graceUntil.getTime()) return { ok: true, grace: true };
236	  return { ok: false, code: "storage_full", usedBytes: total, quotaBytes: a.quotaBytes };
237	}
