239	export const STORAGE_FULL_CODE = "storage_full";
240	export function storageFullMessage(what: WriteKind): string {
241	  const verb = what === "build" ? "start a new build" : what === "upload" ? "upload this file" : what === "pack" ? "save a new pack version" : what === "import" ? "import this mod" : what === "library" ? "add to the library" : "save this asset";
242	  return `Your Cyrus storage is full, so we couldn't ${verb}. Nothing was started or charged. Free up space or add storage under Account, Storage. Installing, keeping and exporting your mods still works.`;
243	}
