249	/** Pure: which finished builds' jars may go (see the header). */
250	export function removableBuilds<T extends { id: string; rootBuildId: string | null; status: string; jarPath: string | null; createdAt: Date; lastInstall: unknown }>(rows: T[], protectedIds: Set<string>): T[] {
251	  const newest = new Map<string, T>();
252	  for (const r of rows) {
253	    if (r.status !== "succeeded") continue;
254	    const k = r.rootBuildId ?? r.id;
255	    const cur = newest.get(k);
256	    if (!cur || r.createdAt.getTime() > cur.createdAt.getTime()) newest.set(k, r);
257	  }
258	  return rows.filter((r) => r.status === "succeeded" && !!r.jarPath && newest.get(r.rootBuildId ?? r.id)?.id !== r.id && !r.lastInstall && !protectedIds.has(r.id));
259	}
