274	export type StorageDeps = { sources: StorageSources; tier: (userId: string) => Promise<TokenTier>; config: () => Promise<StorageConfig>; now: () => Date };
275	let override: Partial<StorageDeps> | null = null;
276	export function setStorageDepsForTests(d: Partial<StorageDeps> | null) { override = d; }
277	const deps = (): StorageDeps => ({ sources: prismaStorageSources(), tier: (u) => tierOf(u), config: () => loadStorageConfig(), now: () => new Date(), ...(override ?? {}) });
