282	/** The add-on GB in force now: an active add-on whose paid period has not ended. */
283	export function effectiveAddonGb(row: Pick<Row, "addonGb" | "addonStatus" | "addonPeriodEnd"> | null, now: Date): number {
284	  if (!row || row.addonStatus !== "active" || !row.addonPeriodEnd || row.addonPeriodEnd.getTime() <= now.getTime()) return 0;
285	  return Math.max(0, row.addonGb);
286	}
