288	export type AccountStorage = {
289	  userId: string; tier: TokenTier; usedBytes: number; pendingBytes: number; quotaBytes: number; planGb: number; addonGb: number;
290	  breakdown: StorageBreakdown | null; computedAt: Date | null; overSince: Date | null; graceUntil: Date | null;
291	  addon: { gb: number; nextGb: number | null; status: string; method: string | null; periodStart: Date | null; periodEnd: Date | null };
292	};
293	function view(row: Row, tier: TokenTier, cfg: StorageConfig, now: Date): AccountStorage {
294	  const addonGb = effectiveAddonGb(row, now);
295	  return {
296	    userId: row.userId, tier, usedBytes: N(row.usedBytes), pendingBytes: N(row.pendingBytes), quotaBytes: quotaBytes(tier, addonGb, cfg), planGb: cfg.quotaGb[tier], addonGb,
297	    breakdown: (row.breakdown as StorageBreakdown | null) ?? null, computedAt: row.computedAt, overSince: row.overSince, graceUntil: row.graceUntil,
298	    addon: { gb: row.addonGb, nextGb: row.addonNextGb, status: row.addonStatus, method: row.addonMethod, periodStart: row.addonPeriodStart, periodEnd: row.addonPeriodEnd },
299	  };
300	}
