302	/** Full recompute of one account: collect -> dedupe/rollup -> quota -> over-quota state -> store. */
303	export async function recomputeStorage(userId: string): Promise<AccountStorage> {
304	  const d = deps();
305	  const now = d.now();
306	  const before = await db.cyrusStorageAccount.findUnique({ where: { userId } });
307	  const pendingSeen = N(before?.pendingBytes);
308	  const [items, tier, cfg] = await Promise.all([collectItems(userId, d.sources), d.tier(userId), d.config()]);
309	  const b = rollup(items);
310	  const quota = quotaBytes(tier, effectiveAddonGb(before, now), cfg);
311	  const over = nextOverState({ usedBytes: b.totalBytes, quotaBytes: quota, prevQuotaBytes: before ? N(before.quotaBytes) : null, prev: before ? { overSince: before.overSince, graceUntil: before.graceUntil } : null, graceDays: cfg.graceDays, now });
312	  const data = { usedBytes: BigInt(b.totalBytes), quotaBytes: BigInt(quota), breakdown: b as unknown as object, computedAt: now, dirtyAt: null, overSince: over.overSince, graceUntil: over.graceUntil };
313	  const row = await db.cyrusStorageAccount.upsert({
314	    where: { userId },
315	    create: { userId, ...data, pendingBytes: BigInt(0) },
316	    // writes that landed while we collected stay pending (they may or may not be in this measurement: never under-count)
317	    update: { ...data, pendingBytes: { decrement: BigInt(pendingSeen) } },
318	  });
319	  if (N(row.pendingBytes) < 0) await db.cyrusStorageAccount.update({ where: { userId }, data: { pendingBytes: BigInt(0) } });
320	  return view({ ...row, pendingBytes: BigInt(Math.max(0, N(row.pendingBytes))) }, tier, cfg, now);
321	}
