323	/** The account's storage as stored, recomputed when missing, stale (24 h) or when its quota went down since. */
324	export async function accountStorage(userId: string): Promise<AccountStorage> {
325	  const d = deps();
326	  const now = d.now();
327	  const row = await db.cyrusStorageAccount.findUnique({ where: { userId } });
328	  if (!row || !row.computedAt || now.getTime() - row.computedAt.getTime() > STALE_MS) return recomputeStorage(userId); // dirty rows: pending bytes already count; the sweep recomputes them
329	  const [tier, cfg] = await Promise.all([d.tier(userId), d.config()]);
330	  const live = quotaBytes(tier, effectiveAddonGb(row, now), cfg);
331	  if (live < N(row.quotaBytes) && N(row.usedBytes) + N(row.pendingBytes) > live) return recomputeStorage(userId); // a drop: start the grace
332	  return view(row, tier, cfg, now);
333	}
