335	export type StorageGate = { ok: true; grace: boolean } | { ok: false; status: 507 | 503; code: string; error: string; usedBytes?: number; quotaBytes?: number };
336	
337	/** THE server-side gate for new builds, uploads, asset saves, library contributions, pack versions and imports.
338	 *  Off = allowed. On = fail CLOSED: if usage cannot be read the write is refused. Never call it for installs,
339	 *  downloads, exports or deletes. */
340	export async function checkStorageWrite(userId: string, addBytes: number, what: WriteKind): Promise<StorageGate> {
341	  if (!storageEnabled()) return { ok: true, grace: false };
342	  try {
343	    const s = await accountStorage(userId);
344	    const d = storageWriteDecision({ usedBytes: s.usedBytes, pendingBytes: s.pendingBytes, quotaBytes: s.quotaBytes, addBytes: Math.max(0, Math.floor(addBytes)), graceUntil: s.graceUntil, now: deps().now() });
345	    if (d.ok) return d;
346	    return { ok: false, status: 507, code: STORAGE_FULL_CODE, error: storageFullMessage(what), usedBytes: d.usedBytes, quotaBytes: d.quotaBytes };
347	  } catch (e) {
