366	/** Sweep (worker, every 5 min): recompute dirty and stale accounts (batch), then today's snapshot once. */
367	export async function storageSweep(batch = 50): Promise<{ recomputed: number; snapshot: boolean }> {
368	  if (!storageEnabled()) return { recomputed: 0, snapshot: false };
369	  const now = deps().now();
370	  const rows = await db.cyrusStorageAccount.findMany({ where: { OR: [{ dirtyAt: { not: null } }, { computedAt: null }, { computedAt: { lt: new Date(now.getTime() - STALE_MS) } }] }, select: { userId: true }, orderBy: { dirtyAt: "asc" }, take: batch });
371	  let recomputed = 0;
372	  for (const r of rows) { try { await recomputeStorage(r.userId); recomputed++; } catch (e) { console.error("[cyrus-storage] recompute", r.userId, (e as Error).message); } }
373	  return { recomputed, snapshot: await takeSnapshot(now) };
374	}
