376	export async function takeSnapshot(now: Date): Promise<boolean> {
377	  const day = dayKey(now);
378	  if (await db.cyrusStorageSnapshot.findUnique({ where: { day }, select: { day: true } })) return false;
379	  const agg = await db.cyrusStorageAccount.aggregate({ _sum: { usedBytes: true, pendingBytes: true }, _count: { userId: true } });
380	  const over = await db.cyrusStorageAccount.count({ where: { overSince: { not: null } } });
381	  const addons = await db.cyrusStorageAccount.aggregate({ where: { addonStatus: "active" }, _sum: { addonGb: true }, _count: { userId: true } });
382	  await db.cyrusStorageSnapshot.create({ data: { day, totalBytes: BigInt(N(agg._sum.usedBytes) + N(agg._sum.pendingBytes)), accounts: agg._count.userId, detail: { over, addonAccounts: addons._count.userId, addonGb: addons._sum.addonGb ?? 0 } } }).catch(() => undefined);
383	  return true;
384	}
