396	export async function assetWriteGate(projectId: string, sha256: string, size: number, origin: string): Promise<AssetGate | null> {
397	  if (!storageEnabled()) return null;
398	  const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { userId: true } });
399	  if (!p) return { ok: true, userId: null, addBytes: 0 };
400	  // content-addressed: bytes already in this account (any project) add nothing
401	  const have = await db.$queryRaw<{ x: number }[]>`SELECT 1 AS x FROM "CyrusProjectAsset" a JOIN "CyrusProject" p ON p.id = a."projectId" WHERE p."userId" = ${p.userId} AND a.sha256 = ${sha256} LIMIT 1`;
402	  const addBytes = have.length ? 0 : Math.max(0, size);
403	  if (!GATED.has(origin) || addBytes === 0) return { ok: true, userId: p.userId, addBytes };
404	  const st = await checkStorageWrite(p.userId, addBytes, "asset");
405	  return st.ok ? { ok: true, userId: p.userId, addBytes } : { ok: false, code: st.code, error: st.error };
406	}
