435	export async function collectItems(userId: string, src: StorageSources): Promise<StorageItem[]> {
436	  const [builds, projects, packs, uploads, library, drafts] = await Promise.all([src.builds(userId), src.projects(userId), src.packs(userId), src.uploads(userId), src.library(userId), src.drafts(userId)]);
437	  const out: StorageItem[] = [];
438	  const labelOf = new Map<string, string>();
439	  for (const b of builds) {
440	    const modId = b.rootBuildId ?? b.id;
441	    if (b.pluginName && !labelOf.has(modId)) labelOf.set(modId, b.pluginName);
442	    if (b.jarPath && b.jarSize) out.push({ key: b.jarSha256 && SHA.test(b.jarSha256) ? `sha256:${b.jarSha256}` : `row:jar:${b.id}`, bytes: b.jarSize, category: "builds", modId, game: "minecraft", label: b.pluginName, at: iso(b.createdAt) });
443	    // hosted resource pack (/tank/cyrus-packs/p/<sha1>.zip via the pack host) + shipped data packs, from the build result
444	    const ra = (b.result as { assets?: { pack?: { sha256?: string; bytes?: number } | null; datapacks?: { sha256?: string; bytes?: number }[] } } | null)?.assets;
445	    for (const pk of [ra?.pack, ...(Array.isArray(ra?.datapacks) ? ra!.datapacks! : [])]) if (pk && Number(pk.bytes) > 0) out.push({ key: pk.sha256 && SHA.test(pk.sha256) ? `sha256:${pk.sha256}` : `row:rp:${b.id}`, bytes: Number(pk.bytes), category: "packs", modId, game: "minecraft", label: b.pluginName, at: iso(b.createdAt) });
446	    const att = (b.cyrus as { attachments?: { n?: number; size?: number }[] } | null)?.attachments;
447	    if (Array.isArray(att)) for (const a of att) if (Number(a?.size) > 0) out.push({ key: `row:att:${b.id}:${a.n ?? 0}`, bytes: Number(a.size), category: "uploads", modId, game: "minecraft", label: b.pluginName, at: iso(b.createdAt) });
448	  }
449	  const proj = new Map(projects.map((p) => [p.id, p]));
450	  const modOf = (projectId: string) => { const p = proj.get(projectId); return p ? (p.rootBuildId ?? `p:${p.id}`) : null; };
451	  const gameOf = (projectId: string) => proj.get(projectId)?.game ?? null;
452	  const lbl = (projectId: string) => { const m = modOf(projectId); return (m && labelOf.get(m)) || proj.get(projectId)?.title || null; };
453	  const ids = projects.map((p) => p.id);
454	  const [assets, revisions] = ids.length ? await Promise.all([src.assets(ids), src.revisions(ids)]) : [[], []];
455	  for (const a of assets) out.push({ key: SHA.test(a.sha256) ? `sha256:${a.sha256}` : `row:asset:${a.id}`, bytes: a.size, category: "assets", modId: modOf(a.projectId), game: gameOf(a.projectId), label: lbl(a.projectId), at: iso(a.createdAt) });
456	  for (const r of revisions) out.push({ key: `row:rev:${r.id}`, bytes: r.bytes, category: "revisions", modId: modOf(r.projectId), game: gameOf(r.projectId), label: lbl(r.projectId), at: iso(r.createdAt) });
457	  for (const d of drafts) out.push({ key: `row:draft:${d.id}`, bytes: d.bytes, category: "drafts", modId: modOf(d.projectId), game: gameOf(d.projectId), label: lbl(d.projectId), at: iso(d.updatedAt) });
458	  for (const p of packs) for (const v of p.versions) out.push({ key: SHA.test(v.sha256) ? `sha256:${v.sha256}` : `row:pack:${p.packId}:${v.versionId}`, bytes: v.bytes, category: "packs", modId: null, game: "minecraft", label: p.name, at: v.createdAt });
459	  for (const u of uploads) out.push({ key: `row:upload:${u.name}`, bytes: u.bytes, category: "uploads", modId: null, game: null, label: null, at: null });
460	  for (const l of library) out.push({ key: SHA.test(l.id) ? `sha256:${l.id}` : `row:lib:${l.id}`, bytes: l.bytes, category: "library", modId: null, game: null, label: null, at: null });
461	  return out;
462	}
