474	async function dirFiles(dir: string): Promise<{ name: string; bytes: number }[]> {
475	  let names: string[];
476	  try { names = await readdir(dir); } catch { return []; }
477	  const out: { name: string; bytes: number }[] = [];
478	  for (const n of names.slice(0, 2000)) { try { const s = await stat(path.join(dir, n)); if (s.isFile()) out.push({ name: n, bytes: s.size }); } catch { /* raced away */ } }
479	  return out;
480	}
