482	export function prismaStorageSources(env: Record<string, string | undefined> = process.env): StorageSources {
483	  const root = cyrusConfig(env).modbuildDir;
484	  return {
485	    builds: (userId) => db.modBuild.findMany({ where: { userId }, select: { id: true, rootBuildId: true, pluginName: true, jarSha256: true, jarSize: true, jarPath: true, createdAt: true, cyrus: true, result: true }, take: 20_000 }),
486	    projects: (userId) => db.cyrusProject.findMany({ where: { userId }, select: { id: true, game: true, rootBuildId: true, title: true }, take: 5_000 }),
487	    assets: (projectIds) => db.cyrusProjectAsset.findMany({ where: { projectId: { in: projectIds } }, select: { id: true, projectId: true, sha256: true, size: true, createdAt: true }, take: 100_000 }),
488	    revisions: (projectIds) => db.$queryRaw<{ id: string; projectId: string; bytes: number; createdAt: Date }[]>`
489	      SELECT id, "projectId", (COALESCE(pg_column_size(spec), 0) + COALESCE(pg_column_size(manifest), 0) + COALESCE(pg_column_size(engine), 0))::int AS bytes, "createdAt"
490	      FROM "CyrusRevision" WHERE "projectId" = ANY(${projectIds}::text[]) LIMIT 200000`,
491	    drafts: (userId) => db.$queryRaw<{ id: string; projectId: string; bytes: number; updatedAt: Date }[]>`
492	      SELECT id, "projectId", COALESCE(pg_column_size(doc), 0)::int AS bytes, "updatedAt" FROM "CyrusModelDraft" WHERE "ownerRef" = ${userId} LIMIT 20000`,
493	    packs: async (userId) => {
494	      if (!/^[A-Za-z0-9_-]{1,64}$/.test(userId)) return [];
495	      const { FsModPackStore } = await import("../modpack/store");
496	      return (await new FsModPackStore().list(userId).catch(() => [])).map((p) => ({ packId: p.packId, name: p.name, versions: p.versions }));
497	    },
498	    uploads: (userId) => dirFiles(path.join(root, "uploads", userId.replace(/[^A-Za-z0-9_-]/g, ""))),
499	    library: async (userId) => {
500	      const { libraryFlags } = await import("../library/backend/flags");
501	      const secret = libraryFlags(env).urlSecret;
502	      if (!secret) return [];
503	      const { contributorIdOf } = await import("../library/backend/studio-hook");
504	      return db.$queryRaw<{ id: string; bytes: number }[]>`
505	        SELECT id, (CASE WHEN (entry->'tech'->>'bytes') ~ '^[0-9]{1,15}$' THEN (entry->'tech'->>'bytes')::bigint ELSE 0 END)::float8 AS bytes
506	        FROM "CyrusCatalogEntry" WHERE "contributorId" = ${contributorIdOf(secret, userId)} AND status <> 'removed' LIMIT 50000`;
507	    },
508	  };
509	}
