// Per BUILD:   model (which Cyrus model was picked), attachments (pasted images).
// Per PROJECT: kept on the project's ROOT build only: title, favourite, notes,
//              headBuildId (the version the owner "restored" / marked current),
//              and (v6) the listing: category + secondaryCategories + categorySource
//              (universal ids, lib/cyrus/categories.ts), description, icon (+ iconData for an
//              uploaded icon until the NxLabs asset store holds it).
import { normalizeCategory, type CyrusCategoryId } from "./categories";
import { isCyrusModel, type CyrusModelId } from "./models";
import { LISTING_DESCRIPTION_MAX, LISTING_ICON_INLINE_MAX, LISTING_SECONDARY_MAX, cleanDescription, isIconRef } from "./listing";
