export const dynamic = "force-dynamic";

// Cyrus: per-project settings (name, favourite, notes, restored version), kept on
// the project's ROOT build. `id` may be any build of the project.
export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const rl = checkRateLimit(`mb:project:${o.user.id}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Slow down a little. Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  const rootId = o.build.rootBuildId ?? o.build.id;
  const root = rootId === o.build.id ? o.build : await cyrusDb.modBuild.findUnique({ where: { id: rootId } });
  if (!root || root.userId !== o.user.id) return NOT_FOUND();
  const heads = await cyrusDb.modBuild.findMany({ where: { userId: o.user.id, status: "succeeded", OR: [{ rootBuildId: rootId }, { id: rootId }] }, select: { id: true } });
  const parsed = parseProjectPatch(await req.json().catch(() => null), heads.map((h) => h.id));
  if (!parsed.ok) return NextResponse.json({ error: parsed.error }, { status: 400 });
  const meta = applyProjectPatch(readCyrusMeta(root.cyrus), parsed.patch);
  await cyrusDb.modBuild.update({ where: { id: rootId }, data: { cyrus: meta as unknown as Prisma.InputJsonValue } });
  return NextResponse.json({ ok: true, rootId, meta });
}
