/** New-mod flow (r39). The build itself is created by the existing build API, which re-checks everything. */
export default async function CyrusNewMod({ searchParams }: { searchParams: Promise<{ like?: string | string[] }> }) {
  await requireModBuilderUser(); // the preview gate first (same 404 as every Cyrus page), then the app switch
  const v = await appViewer();
  // "Make something like this" from a featured mod: the prompt starts from its public title and tagline (nothing else of it).
  const like = (await searchParams).like;
  let likeTitle: string | null = null, initialPrompt = "";
