    const pg = await cyrusDb.cyrusModPage.findFirst({ where: { slug: like, visibility: "PUBLIC", hiddenAt: null }, select: { title: true, tagline: true } }).catch(() => null);
    if (pg) { likeTitle = pg.title; initialPrompt = `Make a mod like "${pg.title}"${pg.tagline ? `: ${pg.tagline}` : ""}. Describe what should be different about mine: `; }
  }
  const [servers, tokens] = await Promise.all([modBuilderServers(v.user.id).catch(() => []), buildTokenState(v.user).catch(() => null)]);
  const cost: CostInfo = tokens?.active
    ? { active: true, enforce: tokens.enforce, available: tokens.available, models: tokens.models, reserve: tokens.reserve }
    : { active: false, enforce: false, available: 0, models: [], reserve: null };
  // v8 capability manifest per live game + version: only templates, studios and prompts that game can use
  const fits: Record<string, GameFitView> = {};
  const switches = await studioSwitches();
  for (const g of CYRUS_GAMES.filter((x) => x.status === "live")) for (const ver of g.versions) {
    const m = usableFor(g.id, ver, { switches });
    fits[`${g.id}@${ver}`] = { templates: m.templates.map((t) => t.id), examples: m.examplePrompts, studios: shownStudios(m).map((x) => STUDIO_LABEL[x.id]), whyNot: m.whyNot.map((w) => ({ title: w.title, reason: w.reason })) };
  }
  return (
    <>
      <header className="cx-head">
        <div>
          <div className="cx-eyebrow">New mod</div>
          <h1 className="cx-h1">What should Cyrus <span className="cx-grad">build</span>?</h1>
          <p className="cx-sub">Say what you want in your own words. Cyrus plans it, shows the cost, then builds it. No setup needed.</p>
        </div>
      </header>
      <NewModFlow games={CYRUS_GAMES} servers={servers} cost={cost} projectBase={v.href(P.projects)} studioHref={v.onCyrus ? "/studio" : "/dashboard/cyrus"} fits={fits} initialPrompt={initialPrompt} likeTitle={likeTitle} />
    </>
  );
}
