195	// Every Cyrus-related Setting in one list, with what it does and its safe default. PURE and
196	// client-safe; unit-tested in test/cyrus-admin.test.ts. The Audit & settings tab renders this and
197	// writes through lib/actions-cyrus-admin.ts (validateSettingValue below, audited before/after).
198	//
199	// `owner` says which branch reads the setting. A setting whose code is not merged yet still shows
200	// here (marked "not merged yet") so the owner can see the whole picture before the merges, but it
201	// does nothing until that code lands.
202	import { CYRUS_TOKEN_DEFAULTS, TOKEN_ENUMS, TOKEN_PLACEHOLDER_KEYS, TOKEN_SETTING_KEYS } from "../tokens/config";
203	import { CYRUS_GAMES } from "../games";
204	import { gameStatusKey } from "../game-status";
205	import { STORAGE_DEFAULTS, STORAGE_SETTING_KEYS, type StorageSettingKey } from "../storage/config";
206	import { PRICING_RULES, validatePriceTable } from "../storage/pricing";
207	
208	export type SettingType = "bool" | "int" | "number" | "enum" | "emails" | "text" | "json";
209	
210	export type CyrusSettingDef = {
211	  key: string;
212	  label: string;
213	  description: string;
214	  type: SettingType;
215	  default: string;
216	  options?: string[];
217	  min?: number;
218	  max?: number;
219	  group: "launch" | "safety" | "games" | "lifecycle" | "tokens" | "features" | "kill" | "cost" | "storage";
220	  /** Branch whose code reads it ("base" = already on feature/cyrus-v6). */
221	  owner: "base" | "admin" | "lifecycle" | "capabilities";
222	  /** Edited on another screen (link) instead of inline here. */
223	  editAt?: string;
224	  /** Flipping it ON affects customers or money: the form asks for a confirm. */
225	  risky?: boolean;
226	};
227	
228	const tokenRange: Record<string, [number, number]> = {
229	  cyrus_tok_tokens_per_usd: [1, 100000],
230	  cyrus_tok_mult_katara: [0.1, 20],
231	  cyrus_tok_mult_saka: [0.1, 20],
232	  cyrus_tok_mult_yakko: [0.1, 20],
233	  cyrus_tok_failed_charge_pct: [0, 100],
234	};
235	
236	function tokenDef(k: (typeof TOKEN_SETTING_KEYS)[number]): CyrusSettingDef {
237	  const d = CYRUS_TOKEN_DEFAULTS[k];
238	  const bool = d === "true" || d === "false";
239	  const json = k === "cyrus_tok_reserve_table";
240	  const price = /^cyrus_tok_price_/.test(k) || k in TOKEN_ENUMS;
241	  const num = !bool && !json && !price;
242	  const r = tokenRange[k];
243	  return {
244	    key: k,
245	    label: k.replace(/^cyrus_tok_/, "").replace(/_/g, " "),
246	    description: `${(TOKEN_PLACEHOLDER_KEYS as readonly string[]).includes(k) ? "PLACEHOLDER default, pending the owner's decision. " : ""}${k in TOKEN_ENUMS ? `One of: ${(TOKEN_ENUMS as Record<string, readonly string[]>)[k].join(", ")}. ` : ""}Token economy setting (docs: "Cyrus token economy"). A blank or bad value falls back to the default, never to 0.`,
247	    type: bool ? "bool" : json ? "json" : price ? "text" : /mult_|per_usd$|pct$/.test(k) ? "number" : "int",
248	    default: d,
249	    ...(num ? { min: r?.[0] ?? 0, max: r?.[1] ?? 1_000_000 } : {}),
250	    group: "tokens",
251	    owner: "base",
252	    ...(json || price ? { editAt: "/admin/cyrus-tokens" } : {}),
253	    // r40: half of the launch pair (with cyrus_studio_public_enabled): only the pair switch on Flags may change it
254	    ...(k === "cyrus_tok_live" ? { editAt: "/admin/cyrus/flags#launch" } : {}),
255	    risky: k === "cyrus_tok_live" || k === "cyrus_tok_enforce",
256	  };
257	}
