260	const STORAGE_LABEL: Record<StorageSettingKey, [string, string]> = {
261	  cyrus_storage_quota_free_gb: ["Storage: Free quota (GB)", "Included storage without a plan. PLACEHOLDER (the owner set no Free number)."],
262	  cyrus_storage_quota_katara_gb: ["Storage: Katara quota (GB)", "Included storage on Katara (owner: 5 GB)."],
263	  cyrus_storage_quota_saka_gb: ["Storage: Saka quota (GB)", "Included storage on Saka (owner: 25 GB)."],
