265	  cyrus_storage_price_table: ["Storage: price bands (monthly)", "JSON list of {fromGb, centsPerGb}; the first band starts at 1 GB, bands go up. Owner's numbers: 1 GB 85c, 5 GB 75c, 25 GB 60c, 50 GB 30c, 100 GB 20c per GB."],
266	  cyrus_storage_pricing_rule: ["Storage: pricing rule", "capped = fewer GB never cost more than the next breakpoint (default, owner to confirm); literal = rate x GB with the 49/50 GB cliff; graduated = each GB at its own band's rate."],
267	  cyrus_storage_addon_max_gb: ["Storage: largest add-on (GB)", "Most extra GB one account may buy."],
268	  cyrus_storage_grace_days: ["Storage: grace after a quota drop (days)", "After a downgrade, cancel, refund or failed renewal an over-quota account keeps writing this long; then new builds and uploads stop until it is under quota. Data is never deleted automatically."],
269	  cyrus_storage_warn_pcts: ["Storage: meter warning levels (%)", "Three ascending percentages, e.g. 80,95,100 (the last = full)."],
270	  cyrus_storage_retention_days: ["Storage: cleanup suggestion age (days)", "Old build versions and drafts untouched this long are suggested for cleanup (never deleted without the customer's confirm)."],
