272	  cyrus_storage_pool_warn_pct: ["Storage: disk/pool warning (%)", "Admin alert when a disk or pool (/, /tank, node-2) passes it."],
273	  cyrus_storage_pool_crit_pct: ["Storage: disk/pool critical (%)", "Urgent admin alert above this."],
274	};
275	const STORAGE_DEFS: CyrusSettingDef[] = STORAGE_SETTING_KEYS.map((k): CyrusSettingDef => {
276	  const [label, description] = STORAGE_LABEL[k];
277	  const type: SettingType = k === "cyrus_storage_price_table" ? "json" : k === "cyrus_storage_pricing_rule" ? "enum" : k === "cyrus_storage_warn_pcts" ? "text" : /_gb$|usd_gb_month$/.test(k) ? "number" : "int";
278	  return {
279	    key: k, label, description: `PLACEHOLDER default pending the owner. ${description}`, type, default: STORAGE_DEFAULTS[k], group: "storage", owner: "base",
280	    ...(type === "enum" ? { options: [...PRICING_RULES] } : {}),
281	    ...(type === "int" || type === "number" ? { min: 0, max: k === "cyrus_storage_addon_max_gb" ? 100_000 : k.endsWith("_pct") ? 100 : 10_000 } : {}),
282	    risky: /quota|price|rule|grace/.test(k),
283	  };
284	});
