339	export const cyrusSettingDef = (key: string) => CYRUS_SETTINGS.find((s) => s.key === key) ?? null;
340	
341	const EMAIL_RE = /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/;
342	
343	/**
344	 * Validate an inline edit. Returns the value to store, "" to clear (back to default), or an error.
345	 * Settings with `editAt` (JSON, game status, Stripe price ids) are refused here: they have their own
346	 * screen with its own validation.
347	 */
348	export function validateSettingValue(key: string, raw: string): { ok: true; value: string } | { ok: false; error: string } {
349	  const def = cyrusSettingDef(key);
350	  if (!def) return { ok: false, error: "Not a Cyrus setting." };
351	  if (def.editAt) return { ok: false, error: `Edit this on ${def.editAt}.` };
352	  const v = raw.trim();
353	  if (v === "" || v === def.default) return { ok: true, value: "" };
354	  if (key === "cyrus_storage_price_table") { const t = validatePriceTable(v); return t.ok ? { ok: true, value: JSON.stringify(t.table) } : t; }
355	  if (key === "cyrus_storage_warn_pcts") {
356	    const w = v.split(",").map((x) => Number(x.trim()));
357	    return w.length === 3 && w.every((x) => Number.isInteger(x) && x >= 1 && x <= 100) && w[0] < w[1] && w[1] < w[2] ? { ok: true, value: w.join(",") } : { ok: false, error: "Use three ascending percentages, e.g. 80,95,100." };
358	  }
359	  switch (def.type) {
360	    case "bool":
361	      return v === "true" || v === "false" ? { ok: true, value: v } : { ok: false, error: "Use true or false." };
362	    case "enum":
363	      return def.options?.includes(v) ? { ok: true, value: v } : { ok: false, error: `Use one of: ${def.options?.join(", ")}.` };
364	    case "int":
365	    case "number": {
366	      const n = Number(v);
367	      if (!Number.isFinite(n) || (def.type === "int" && !Number.isInteger(n))) return { ok: false, error: def.type === "int" ? "Use a whole number." : "Use a number." };
368	      if (def.min !== undefined && n < def.min) return { ok: false, error: `At least ${def.min}.` };
369	      if (def.max !== undefined && n > def.max) return { ok: false, error: `At most ${def.max}.` };
370	      return { ok: true, value: String(n) };
371	    }
372	    case "emails": {
373	      const list = v.split(/[,\s;]+/).map((e) => e.trim().toLowerCase()).filter(Boolean);
374	      const bad = list.find((e) => !EMAIL_RE.test(e));
375	      if (bad) return { ok: false, error: `Not an email: ${bad.slice(0, 60)}` };
376	      return { ok: true, value: [...new Set(list)].join(",") };
377	    }
378	    case "text":
379	      if (key === "cyrus_mail_from" && !/^(?:[^<>@\r\n]{1,60} )?<?[a-z0-9._+-]{1,64}@cyrus\.my>?$/i.test(v)) return { ok: false, error: "Use an address on cyrus.my, e.g. Cyrus <hello@cyrus.my>." };
380	      return v.length <= 200 ? { ok: true, value: v } : { ok: false, error: "Too long." };
381	    default:
382	      return { ok: false, error: "This setting cannot be edited here." };
383	  }
384	}
