// Cyrus game status overrides (admin, /admin/cyrus/games). PURE and client-safe.
//
// lib/cyrus/games.ts stays the DEFAULT (the file is the source of truth for what each game is);
// a Setting `cyrus_game_<id>_status` = live | soon | disabled overrides one game's status without a
// deploy. Server code reads the effective list with loadCyrusGameStatuses() in
// lib/cyrus/game-status.server.ts.
//
// Safety rules (canSetGameStatus, unit-tested):
//  - "live" is only allowed for a game the build pipeline can really build for (CYRUS_BUILDABLE_GAMES).
//    A game whose mods are template previews today can be "soon" or "disabled", never "live", so a
//    toggle can never advertise a product that does not exist.
//  - "disabled" hides the game and refuses new builds for it (lib/modbuilder/create.ts asks
//    cyrusGameBuildable()); existing projects, downloads and installs are untouched.
//  - Clearing the override (back to the file default) is always allowed.
import { CYRUS_GAMES, type CyrusGame } from "./games";

export type CyrusGameAdminStatus = "live" | "soon" | "disabled";
export const CYRUS_GAME_STATUSES: CyrusGameAdminStatus[] = ["live", "soon", "disabled"];

/** Games with a real AI build pipeline today (the Minecraft build service). Update when one lands. */
export const CYRUS_BUILDABLE_GAMES: readonly string[] = ["minecraft"];

export const gameStatusKey = (id: string) => `cyrus_game_${id}_status`;
export const GAME_STATUS_KEY_RE = /^cyrus_game_([a-z0-9]{2,20})_status$/;

export const isGameStatus = (v: unknown): v is CyrusGameAdminStatus => typeof v === "string" && (CYRUS_GAME_STATUSES as string[]).includes(v);

export type EffectiveGame = CyrusGame & { adminStatus: CyrusGameAdminStatus; defaultStatus: CyrusGameAdminStatus; overridden: boolean };

/** Merge stored overrides (key -> value) over the file defaults. Unknown or bad values are ignored. */
export function applyGameStatusOverrides(games: CyrusGame[], stored: Record<string, string | undefined>): EffectiveGame[] {
  return games.map((g) => {
    const raw = stored[gameStatusKey(g.id)];
    const def: CyrusGameAdminStatus = g.status;
    // A stored "live" for a game that cannot build is ignored (fails safe to the default).
    const ok = isGameStatus(raw) && (raw !== "live" || CYRUS_BUILDABLE_GAMES.includes(g.id));
    const s: CyrusGameAdminStatus = ok ? (raw as CyrusGameAdminStatus) : def;
    const status = s === "live" ? "live" : "soon";
    return {
      ...g,
      status,
      available: s === "live",
      note: s === "live" ? g.builds : s === "disabled" ? "Unavailable" : "Coming soon",
      adminStatus: s,
      defaultStatus: def,
      overridden: ok && s !== def,
    };
  });
}

export function canSetGameStatus(gameId: string, next: CyrusGameAdminStatus | "default"): { ok: true } | { ok: false; error: string } {
  if (!CYRUS_GAMES.some((g) => g.id === gameId)) return { ok: false, error: "Unknown game." };
  if (next === "default" || next === "soon" || next === "disabled") return { ok: true };
  if (next === "live" && CYRUS_BUILDABLE_GAMES.includes(gameId)) return { ok: true };
  if (next === "live") return { ok: false, error: "This game has no real build pipeline yet, so it cannot be made live from here." };
  return { ok: false, error: "Pick live, soon or disabled." };
}

