// Cyrus game slots (D-63), SERVER ONLY: what an account mods today (from its own rows), the fast pre-check and the
// RACE-SAFE claim used at every creation path. Rules: ./game-slots.ts. HOST SEAM: Cyrus tables via cyrusDb only.
//
// IN USE (one account): every ModBuild chain root (game "minecraft": ModBuild has no game column, every build today is
// a Minecraft plugin) whose root meta is not archived, plus every CyrusProject whose game differs or that has no root
// build (a build-less project cannot be archived yet: when a game lands with build-less projects it needs an archive
// flag on CyrusProject, see docs/cyrus/12). A project with a root build follows that root's archived flag.
//
// RACE: two creates that would each take the LAST slot. withGameSlot() takes a per-account Postgres advisory lock
// inside a transaction, re-reads the usage on that transaction, decides, and runs the insert on the SAME transaction,
// so the second create sees the first one's row and is refused. A create in a game already in use takes no lock.
import { cyrusDb as db, type CyrusDb } from "../db";
import { getHost } from "../host";
import { CYRUS_GAMES } from "../games";
import { tokensActiveFor } from "./access";
import { loadTokenConfig, type TokenConfig, type TokenTier } from "./config";
import { activeGameSlotOverride, gameSlotDecision, gamesInUse, gamesLimit, GAME_SLOT_OVERRIDES_KEY, GAME_SLOTS_FULL, parseGameSlotOverrides, type GameSlotOverride, type GameUsageRow } from "./game-slots";

type Tx = Pick<CyrusDb, "$queryRaw">;
export type SlotUser = { id: string; email?: string | null };

export type GameSlotDeps = {
  /** in the token economy and cyrus_tok_enforce on (the same switch as the model unlock) */
  enforced(user: SlotUser, cfg: TokenConfig): Promise<boolean>;
  tier(userId: string, cfg: TokenConfig): Promise<TokenTier>;
  config(): Promise<TokenConfig>;
  overrides(): Promise<GameSlotOverride[]>;
  now(): Date;
};
let testDeps: Partial<GameSlotDeps> | null = null;
export function setGameSlotDepsForTests(d: Partial<GameSlotDeps> | null) { testDeps = d; }
const deps = (): GameSlotDeps => ({
  enforced: async (u, cfg) => {
    if (!cfg.enforce) return false;
    const user = u.email !== undefined ? u : await getHost().users.get(u.id).catch(() => null);
    return tokensActiveFor(user ? { id: u.id, email: user.email ?? null } : null, cfg);
  },
  tier: async (userId, cfg) => (await import("./access")).tierOf(userId, cfg),
  config: () => loadTokenConfig(),
  overrides: loadGameSlotOverrides,
  now: () => new Date(),
  ...(testDeps ?? {}),
});

export async function loadGameSlotOverrides(): Promise<GameSlotOverride[]> {
  try { return parseGameSlotOverrides((await getHost().settings.readStored([GAME_SLOT_OVERRIDES_KEY]))[GAME_SLOT_OVERRIDES_KEY]); }
  catch { return []; }
}

export const gameName = (id: string) => CYRUS_GAMES.find((g) => g.id === id)?.name ?? id;

/** The account's usage rows (one per project / build chain). `client` = a transaction inside withGameSlot. */
export async function gameUsageRows(userId: string, client: Tx = db): Promise<GameUsageRow[]> {
  const builds = await client.$queryRaw<{ archived: boolean }[]>`
    SELECT COALESCE(cyrus->>'archived', '') = 'true' AS archived FROM "ModBuild"
    WHERE "userId" = ${userId} AND ("rootBuildId" IS NULL OR "rootBuildId" = id) LIMIT 20000`;
  const projects = await client.$queryRaw<{ game: string; archived: boolean }[]>`
    SELECT p.game, COALESCE(b.cyrus->>'archived', '') = 'true' AS archived FROM "CyrusProject" p
    LEFT JOIN "ModBuild" b ON b.id = p."rootBuildId" AND b."userId" = p."userId"
    WHERE p."userId" = ${userId} LIMIT 20000`;
  return [...builds.map((b) => ({ game: "minecraft", archived: !!b.archived })), ...projects.map((p) => ({ game: p.game, archived: !!p.archived }))];
}

export const accountGames = async (userId: string, client: Tx = db): Promise<string[]> => gamesInUse(await gameUsageRows(userId, client));

export type GameSlotState = { enforced: boolean; tier: TokenTier; limit: number; planLimit: number; override: GameSlotOverride | null; inUse: string[] };

/** For the UI (picker, account page, admin): never throws; an error reads as "not enforced, nothing in use". */
export async function gameSlotState(user: SlotUser): Promise<GameSlotState> {
  const d = deps();
  const cfg = await d.config();
  try {
    const [enforced, tier, list, inUse] = await Promise.all([d.enforced(user, cfg), d.tier(user.id, cfg), d.overrides(), accountGames(user.id)]);
    const override = activeGameSlotOverride(list, user.id, d.now());
    return { enforced, tier, limit: gamesLimit(tier, cfg, override), planLimit: gamesLimit(tier, cfg, null), override, inUse };
  } catch (e) {
    console.error("[cyrus-game-slots] state", user.id, (e as Error).message);
    return { enforced: false, tier: "free", limit: cfg.plan.games.free, planLimit: cfg.plan.games.free, override: null, inUse: [] };
  }
}

export type GameSlotRefusal = { ok: false; status: 403 | 503; code: string; error: string; used?: number; limit?: number; upgrade?: TokenTier | null };
export type GameSlotCheck = { ok: true; takesSlot: boolean; enforced: boolean } | GameSlotRefusal;

const UNKNOWN: GameSlotRefusal = { ok: false, status: 503, code: "game_slots_unknown", error: "We couldn't check your plan's game slots just now, so nothing was started or charged. Please try again in a minute." };

async function decide(user: SlotUser, game: string, client: Tx): Promise<GameSlotCheck> {
  const d = deps();
  const cfg = await d.config();
  if (!(await d.enforced(user, cfg))) return { ok: true, takesSlot: false, enforced: false };
  const [tier, list, inUse] = await Promise.all([d.tier(user.id, cfg), d.overrides(), accountGames(user.id, client)]);
  const limit = gamesLimit(tier, cfg, activeGameSlotOverride(list, user.id, d.now()));
  const r = gameSlotDecision({ inUse, game, limit, tier, cfg, nameOf: gameName });
  if (r.ok) return { ok: true, takesSlot: r.takesSlot, enforced: true };
  return { ok: false, status: 403, code: r.code, error: r.error, used: r.used, limit: r.limit, upgrade: r.upgrade };
}

/** Fast pre-check (no lock) for an early, clear refusal before tokens are held. Fails CLOSED when enforcement is on. */
export async function checkGameSlot(user: SlotUser, game: string): Promise<GameSlotCheck> {
  try { return await decide(user, game, db); }
  catch (e) { console.error("[cyrus-game-slots] check failed closed", user.id, (e as Error).message); return UNKNOWN; }
}

export class GameSlotError extends Error {
  constructor(public refusal: GameSlotRefusal) { super(refusal.error); this.name = "GameSlotError"; }
}

/**
 * The race-safe claim: run `insert` (the row that makes the game "in use") only if the slot is still free, under a
 * per-account advisory lock on one transaction. Not enforced or game already in use: `insert` runs on the plain client.
 * A lost race / full plan = { ok: false } and `insert` never ran.
 */
export async function withGameSlot<T>(user: SlotUser, game: string, insert: (client: CyrusDb) => Promise<T>): Promise<{ ok: true; value: T } | GameSlotRefusal> {
  let pre: GameSlotCheck;
  try { pre = await decide(user, game, db); } catch (e) { console.error("[cyrus-game-slots] claim failed closed", user.id, (e as Error).message); return UNKNOWN; }
  if (!pre.ok) return pre;
  if (!pre.takesSlot) return { ok: true, value: await insert(db) };
  try {
    const value = await db.$transaction(async (tx) => {
      const t = tx as unknown as CyrusDb;
      await t.$queryRaw`SELECT 1 AS x FROM pg_advisory_xact_lock(hashtext(${`cyrus-game-slot:${user.id}`}))`;
      const again = await decide(user, game, t);
      if (!again.ok) throw new GameSlotError(again);
      return insert(t);
    }, { timeout: 20_000 });
    return { ok: true, value };
  } catch (e) {
    if (e instanceof GameSlotError) return e.refusal;
    throw e;
  }
}

/** Building on an archived project brings it back: clear the root's archived flag (best effort). */
export async function unarchiveRoot(rootId: string): Promise<void> {
  const r = await db.modBuild.findUnique({ where: { id: rootId }, select: { cyrus: true } }).catch(() => null);
  const m = (r?.cyrus ?? null) as Record<string, unknown> | null;
  if (!m || m.archived !== true) return;
  const { archived: _a, ...rest } = m; void _a;
  await db.modBuild.update({ where: { id: rootId }, data: { cyrus: rest as object } }).catch(() => undefined);
}

export { GAME_SLOTS_FULL };

