/** Top of a legacy fork chain (forks made before CyrusRemix existed). */
async function legacyOrigin(page: CyrusModPage): Promise<string> {
  let cur: Pick<CyrusModPage, "id" | "forkOfPageId" | "rootBuildId"> = page;
  for (let i = 0; i < 25 && cur.forkOfPageId; i++) {
    const r = await cyrusDb.cyrusRemix.findUnique({ where: { buildId: cur.rootBuildId } });
    if (r) return r.originPageId;
    const next = await cyrusDb.cyrusModPage.findUnique({ where: { id: cur.forkOfPageId }, select: { id: true, forkOfPageId: true, rootBuildId: true } });
    if (!next) break;
    cur = next;
  }
  return cur.id;
}
