// D-63/D-64: the ONE plan comparison (help Plans page + account Plan and billing), rendered from planComparison()
// (lib/cyrus/content/plan-table.ts, the live settings). No hooks: works in server components.
import { PLAN_ROWS, type PlanColumn, type PlanRowKey } from "@/lib/cyrus/content/plan-table";
import type { TokenTier } from "@/lib/cyrus/tokens/config-pure";

export function PlanCompare({ columns, current, caption }: { columns: PlanColumn[]; current?: TokenTier | null; caption?: string }) {
  const cell = (c: PlanColumn, k: PlanRowKey) => {
    if (k === "price") return c.priceKnown ? <b>{c.price}</b> : <span className="cx-faint" data-placeholder="price">{c.price}</span>;
    if (k === "tokens") return <>{c.tokens}{c.estimate ? <span className="cx-faint cx-pc-sub">{c.estimate}</span> : null}</>;
    if (k === "games") return c.gamesN === 0 ? <b>{c.games}</b> : c.games;
    return c[k];
  };
  return (
    <div className="cx-pc-wrap" role="region" aria-label={caption ?? "Plan comparison"} tabIndex={0}>
      <table className="cx-pc">
        {caption ? <caption className="cx-faint">{caption}</caption> : null}
        <thead><tr><th scope="col"><span className="cx-sr">Feature</span></th>{columns.map((c) => <th key={c.tier} scope="col" aria-current={current === c.tier ? "true" : undefined}>{c.name}{current === c.tier ? <span className="cx-pill cx-pc-you">Your plan</span> : null}</th>)}</tr></thead>
        <tbody>
          {PLAN_ROWS.map((r) => (
            <tr key={r.key}><th scope="row">{r.label}</th>{columns.map((c) => <td key={c.tier} data-current={current === c.tier ? "1" : undefined}>{cell(c, r.key)}</td>)}</tr>
