// D-64 storage meter math for the compact meters (account, project page, next to upload / library actions). PURE +
// client-safe; unit-tested in test/cyrus-storage-meter.test.ts. Same rules as the Storage tab: used = measured +
// pending, quota = plan GB + add-on, levels from cyrus_storage_warn_pcts, "blocked" only when full AND no grace runs
// (the server gate in ./service.ts makes the real decision; this is the display).
import { meterLevel, type MeterLevel, type StorageConfig } from "./config";
import { fmtBytes, GB } from "./pricing";

export type MeterView = {
  on: boolean; usedBytes: number; quotaBytes: number; pct: number; barPct: number; level: MeterLevel;
  blocked: boolean; grace: boolean; graceUntil: string | null; leftBytes: number; text: string; hint: string | null;
};

export function storageMeterView(a: { on: boolean; usedBytes: number; pendingBytes?: number; quotaBytes: number; graceUntil?: Date | null; now: Date; cfg: Pick<StorageConfig, "warnPcts"> }): MeterView {
  const used = Math.max(0, a.usedBytes) + Math.max(0, a.pendingBytes ?? 0);
  const quota = Math.max(0, a.quotaBytes);
  const m = meterLevel(used, quota, a.cfg);
  const grace = !!a.graceUntil && a.graceUntil.getTime() > a.now.getTime() && used > quota;
  const blocked = a.on && m.level === "full" && !grace;
  const left = Math.max(0, quota - used);
  const text = a.on ? `${fmtBytes(used)} of ${fmtBytes(quota)} used` : `${fmtBytes(quota)} included with your plan`;
  const hint = !a.on ? "Storage limits are not switched on yet: nothing is measured or blocked."
    : blocked ? "Storage full: new builds, uploads and library contributions are paused. Installs and downloads still work."
    : grace ? `Over your storage after a plan change: everything keeps working until ${a.graceUntil!.toISOString().slice(0, 10)}.`
    : m.level === "high" ? `Almost full: ${fmtBytes(left)} left.`
    : m.level === "warn" ? `${fmtBytes(left)} left.`
    : null;
  return { on: a.on, usedBytes: used, quotaBytes: quota, pct: a.on ? m.pct : 0, barPct: a.on ? Math.min(100, m.pct) : 0, level: a.on ? m.level : "ok", blocked, grace, graceUntil: grace ? a.graceUntil!.toISOString() : null, leftBytes: left, text, hint };
}

/** Plan GB -> bytes (1 GB = 2^30, like the quota). */
export const gbBytes = (gb: number) => Math.round(Math.max(0, gb) * GB);
EOF
cat > components/cyrus/app/StorageMeter.tsx <<'EOF'
// D-64 compact storage meter (server component): account page, project page, next to upload / library actions.
// Reads only the viewer's own account; never throws (an error shows nothing rather than a wrong number).
import { accountStorage } from "@/lib/cyrus/storage/service";
import { loadStorageConfig, storageEnabled } from "@/lib/cyrus/storage/config";
import { gbBytes, storageMeterView } from "@/lib/cyrus/storage/meter";

export async function StorageMeter({ userId, href, label = "Storage" }: { userId: string; href: string; label?: string }) {
  try {
    const cfg = await loadStorageConfig();
    const on = storageEnabled();
    const s = on ? await accountStorage(userId) : null;
    const tierGb = s ? null : cfg.quotaGb.free;
    const m = storageMeterView({ on, usedBytes: s?.usedBytes ?? 0, pendingBytes: s?.pendingBytes ?? 0, quotaBytes: s?.quotaBytes ?? gbBytes(tierGb ?? 0), graceUntil: s?.graceUntil ?? null, now: new Date(), cfg });
    if (!on) return <div className="cx-st-mini" data-storage="off"><div className="cx-st-mini-row"><span className="cx-muted">{label}</span><span className="cx-faint">Limits not switched on yet</span><a className="cx-btn cx-btn-sm" href={href} style={{ marginLeft: "auto" }}>Details</a></div></div>;
    return (
      <div className={`cx-st-mini cx-st-meter cx-st-${m.level}`} data-storage={m.blocked ? "full" : m.level}>
        <div className="cx-st-mini-row"><span className="cx-muted">{label}</span><b>{m.text}</b><span className="cx-faint">{m.pct}%</span><a className="cx-btn cx-btn-sm" href={href} style={{ marginLeft: "auto" }}>{m.level === "ok" ? "Details" : "Manage storage"}</a></div>
        <div className="cx-st-bar" role="meter" aria-valuemin={0} aria-valuemax={100} aria-valuenow={m.barPct} aria-label={`${label} used`}><i style={{ width: `${m.barPct}%` }} /></div>
        {m.hint ? <span className={m.blocked ? "cx-error" : "cx-faint"} role={m.blocked ? "alert" : undefined} style={{ fontSize: 12.5 }}>{m.hint}</span> : null}
      </div>
    );
  } catch {
    return null;
  }
}
EOF

