/** D-63: archive / restore a project. Archived keeps everything (installs, downloads, history); a game's slot frees
 *  when every project in it is archived. Restoring may need a free game slot again (the API says so plainly). */
export function ArchiveProject({ projectId, archived }: { projectId: string; archived: boolean }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const go = async () => {
    if (!archived && !confirm("Archive this project? It keeps working on your servers and you can still download it; it just stops counting toward your plan's games. You can restore it any time.")) return;
    setBusy(true); setErr(null);
    const r = await fetch(`/api/mod-builder/projects/${encodeURIComponent(projectId)}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ archived: !archived }) }).catch(() => null);
    const j = (await r?.json().catch(() => ({}))) as { ok?: boolean; error?: string } | undefined;
    setBusy(false);
    if (!r || !r.ok || !j?.ok) { setErr(j?.error || "That didn't work. Please try again."); return; }
    router.refresh();
  };
  return <span style={{ display: "inline-flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>{err ? <span className="cx-error" role="alert">{err}</span> : null}<button type="button" className="cx-btn cx-btn-sm" onClick={go} disabled={busy}>{busy ? "…" : archived ? "Restore project" : "Archive project"}</button></span>;
}
