import { GAME_SLOT_OVERRIDES_KEY, pruneGameSlotOverrides, removeGameSlotOverride, upsertGameSlotOverride } from "./cyrus/tokens/game-slots";
import { loadGameSlotOverrides } from "./cyrus/tokens/game-slots.server";''',1)
old='''export async function adminCyrusSuspend(fd: FormData) {'''
s=s.replace(old,'''/** D-63: set (or remove) an account's game slots. It REPLACES the plan's number while it runs; 0 = unlimited. Same
 *  permission as a tier comp (billing area). Stored in the JSON setting cyrus_game_slot_overrides, audited. */
export async function adminCyrusGameSlots(fd: FormData) {
  const admin = await guard("tokens.comp");
  const u = await targetUser(fd.get("user"));
  if (!u) go(fd, "err", "No such account.");
  const raw = str(fd, "games", 6);
  const now = new Date();
  const list = pruneGameSlotOverrides(await loadGameSlotOverrides(), now);
  const before = list.find((o) => o.userId === u.id) ?? null;
  if (raw === "") {
    if (!before) go(fd, "ok", "No override to remove.");
    const next = removeGameSlotOverride(list, u.id);
    await setOrClear(GAME_SLOT_OVERRIDES_KEY, next.length ? JSON.stringify(next) : null);
    await cyrusAudit({ actorId: admin.id, action: "tokens.comp", target: `user:${u.id}`, before, after: null, note: `game slots: back to the plan. ${str(fd, "note")}`.trim() });
    go(fd, "ok", `${u.email} is back to the plan's game slots.`);
  }
  const games = Number(raw);
  if (!Number.isInteger(games) || games < 0 || games > 1000) go(fd, "err", "Game slots must be a whole number from 0 (unlimited) to 1000.");
  const days = Math.floor(Number(fd.get("days")));
  const entry = { userId: u.id, games, note: str(fd, "note", 300), by: admin.id, at: now.toISOString(), until: days > 0 ? new Date(now.getTime() + Math.min(3650, days) * DAY).toISOString() : null };
  await setOrClear(GAME_SLOT_OVERRIDES_KEY, JSON.stringify(upsertGameSlotOverride(list, entry)));
  await cyrusAudit({ actorId: admin.id, action: "tokens.comp", target: `user:${u.id}`, before, after: entry, note: `game slots ${games === 0 ? "unlimited" : games}. ${entry.note}`.trim() });
  go(fd, "ok", `${u.email} may now mod ${games === 0 ? "unlimited games" : `${games} game${games === 1 ? "" : "s"}`}${entry.until ? ` until ${entry.until.slice(0, 10)}` : ""}.`);
}

export async function adminCyrusSuspend(fd: FormData) {''',1)
