// D-64 storage launch readiness: meter math, the grace / over-quota behaviour end to end as r51 intends (pure state
// machine + write rule in sequence), what counts, quota defaults, and the read-only readiness mode of the smoke script.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { storageMeterView } from "../lib/cyrus/storage/meter";
import { meterLevel, parseStorageConfig, quotaBytes } from "../lib/cyrus/storage/config";
import { nextOverState, rollup, storageWriteDecision, type OverState } from "../lib/cyrus/storage/accounting";
import { collectItems, type StorageSources } from "../lib/cyrus/storage/collect";
import { GB } from "../lib/cyrus/storage/pricing";

const cfg = parseStorageConfig({});
const now = new Date("2026-10-13T12:00:00Z");
const DAY = 86_400_000;

describe("quotas (PLACEHOLDER defaults, owner's numbers for paid plans)", () => {
  it("Free 1, Katara 5, Saka 25, Yakko 50 GB; add-on adds on top", () => {
    assert.deepEqual(cfg.quotaGb, { free: 1, katara: 5, saka: 25, all: 50 });
    assert.equal(quotaBytes("saka", 10, cfg), 35 * GB);
    assert.equal(quotaBytes("free", -3, cfg), 1 * GB);
  });
});

describe("meter math", () => {
  it("levels at 80 / 95 / 100 %, pending bytes count, bar capped at 100", () => {
    const q = 10 * GB;
    const v = (used: number, pending = 0) => storageMeterView({ on: true, usedBytes: used, pendingBytes: pending, quotaBytes: q, now, cfg });
    assert.equal(v(1 * GB).level, "ok");
    assert.equal(v(7.9 * GB).level, "ok");
    assert.equal(v(8 * GB).level, "warn");
    assert.equal(v(7 * GB, 1.5 * GB).level, "high");
    assert.equal(v(9.5 * GB).level, "high");
    assert.equal(v(10 * GB).level, "full");
    assert.equal(v(12 * GB).barPct, 100);
    assert.equal(v(12 * GB).pct, 120);
    assert.equal(v(12 * GB).blocked, true);
    assert.equal(v(2.5 * GB).leftBytes, 7.5 * GB);
    assert.equal(v(1 * GB).text, "1.00 GB of 10.0 GB used");
    assert.equal(v(8 * GB).hint, "2.00 GB left.");
  });
  it("grace: over quota but writable until the date; off: nothing measured or blocked", () => {
    const g = storageMeterView({ on: true, usedBytes: 12 * GB, quotaBytes: 10 * GB, graceUntil: new Date(now.getTime() + 5 * DAY), now, cfg });
    assert.equal(g.blocked, false);
    assert.equal(g.grace, true);
    assert.match(g.hint ?? "", /until 2026-10-18/);
    const off = storageMeterView({ on: false, usedBytes: 50 * GB, quotaBytes: 1 * GB, now, cfg });
    assert.equal(off.blocked, false);
    assert.equal(off.level, "ok");
    assert.match(off.hint ?? "", /not switched on/);
  });
  it("quota 0: anything stored is full", () => {
    assert.equal(meterLevel(1, 0, cfg).level, "full");
    assert.equal(meterLevel(0, 0, cfg).level, "ok");
  });
});

describe("over quota end to end (the r51 rules, unchanged)", () => {
  const graceDays = cfg.graceDays;
  const step = (st: OverState | null, used: number, quota: number, prevQuota: number | null, at: Date) => nextOverState({ usedBytes: used, quotaBytes: quota, prevQuotaBytes: prevQuota, prev: st, graceDays, now: at });
  const write = (st: OverState, used: number, quota: number, add: number, at: Date) => storageWriteDecision({ usedBytes: used, pendingBytes: 0, quotaBytes: quota, addBytes: add, graceUntil: st.graceUntil, now: at });

  it("downgrade Saka 25 -> Katara 5 with 12 GB: 30-day grace, writes keep working, then paused, then free again", () => {
    let st = step(null, 12 * GB, 25 * GB, null, now);
    assert.deepEqual(st, { overSince: null, graceUntil: null });
    st = step(st, 12 * GB, 5 * GB, 25 * GB, now); // the quota dropped
    assert.equal(st.graceUntil?.getTime(), now.getTime() + graceDays * DAY);
    assert.deepEqual(write(st, 12 * GB, 5 * GB, 0, new Date(now.getTime() + 10 * DAY)), { ok: true, grace: true });
    const later = new Date(now.getTime() + (graceDays + 1) * DAY);
    st = step(st, 12 * GB, 5 * GB, 5 * GB, later); // grace keeps its date
    const refused = write(st, 12 * GB, 5 * GB, 1024, later);
    assert.equal(refused.ok, false);
    assert.equal(!refused.ok && refused.code, "storage_full");
    st = step(st, 4 * GB, 5 * GB, 5 * GB, later); // they cleaned up
    assert.deepEqual(st, { overSince: null, graceUntil: null });
    assert.deepEqual(write(st, 4 * GB, 5 * GB, 512 * 1024 * 1024, later), { ok: true, grace: false });
  });
  it("going over by your own writes has no grace; the first measurement over quota (launch day) gets one", () => {
    const st = step({ overSince: null, graceUntil: null }, 6 * GB, 5 * GB, 5 * GB, now);
    assert.equal(st.graceUntil, null);
    assert.equal(write(st, 6 * GB, 5 * GB, 0, now).ok, false);
    assert.ok(step(null, 6 * GB, 5 * GB, null, now).graceUntil, "launch day: a first measurement over quota starts the grace");
  });
  it("a build (unknown size) needs room left; an upload must fit entirely", () => {
    const st: OverState = { overSince: null, graceUntil: null };
    assert.equal(write(st, 5 * GB - 1, 5 * GB, 0, now).ok, true);
    assert.equal(write(st, 5 * GB, 5 * GB, 0, now).ok, false);
    assert.equal(write(st, 4 * GB, 5 * GB, 1 * GB, now).ok, true);
    assert.equal(write(st, 4 * GB, 5 * GB, 1 * GB + 1, now).ok, false);
  });
});

describe("what counts", () => {
  it("builds (jars), assets, resource + data packs, Mod Pack versions, revisions, drafts, uploads, library; shared bytes once", async () => {
    const SHA = (c: string) => c.repeat(64).slice(0, 64);
    const srcs: StorageSources = {
      builds: async () => [{ id: "b1", rootBuildId: null, pluginName: "Mod", jarSha256: SHA("a"), jarSize: 1000, jarPath: "/x.jar", createdAt: now, cyrus: { attachments: [{ n: 1, size: 50 }] }, result: { assets: { pack: { sha256: SHA("p"), bytes: 300 }, datapacks: [{ sha256: SHA("d"), bytes: 40 }] } } }],
      projects: async () => [{ id: "p1", game: "minecraft", rootBuildId: "b1", title: null }],
      assets: async () => [{ id: "a1", projectId: "p1", sha256: SHA("t"), size: 200, createdAt: now }, { id: "a2", projectId: "p1", sha256: SHA("p"), size: 300, createdAt: now }],
      revisions: async () => [{ id: "r1", projectId: "p1", bytes: 10, createdAt: now }],
      drafts: async () => [{ id: "d1", projectId: "p1", bytes: 5, updatedAt: now }],
      packs: async () => [{ packId: "k1", name: "Pack", versions: [{ versionId: "v1", sha256: SHA("k"), bytes: 700, createdAt: now.toISOString() }] }],
      uploads: async () => [{ name: "u.png", bytes: 20 }],
      library: async () => [{ id: SHA("l"), bytes: 60 }],
    };
    const b = rollup(await collectItems("u1", srcs));
    assert.deepEqual(b.byCategory, { builds: 1000, assets: 500, packs: 740, revisions: 10, drafts: 5, uploads: 70, library: 60 });
    assert.equal(b.dedupedBytes, 300, "the resource pack also stored as an asset counts once");
    assert.equal(b.totalBytes, 1000 + 500 + 740 - 300 + 10 + 5 + 70 + 60);
  });
});

describe("readiness mode (scripts/cyrus/smoke-readonly.sh storage)", () => {
  it("read only, reports READY / NOT READY per piece, never fails on a switch that is off", () => {
    const dir = mkdtempSync(path.join(tmpdir(), "cyrus-ready-"));
    const envf = path.join(dir, "env");
    writeFileSync(envf, "CYRUS_STORAGE=0\nCYRUS_STORAGE_ADDONS=0\n");
    const r = spawnSync("bash", [path.join(__dirname, "..", "scripts/cyrus/smoke-readonly.sh"), "storage"], { env: { ...process.env, ENVF: envf, CYRUS_STORAGE_REPORT: path.join(dir, "none.json") }, encoding: "utf8" });
    const out = r.stdout;
    assert.match(out, /== storage readiness/);
    assert.match(out, /FAIL no DATABASE_URL/, "without a DB it says so (the owner runs it on the primary)");
    assert.match(out, /NOT READY addons/);
    assert.match(out, /NOT READY report/);
    assert.match(out, /READY     alerts/);
    assert.match(out, /summary NOT READY: addons report/);
    assert.doesNotMatch(out, /== migrations|== flags/, "only the storage mode runs");
    const s = readFileSync(path.join(__dirname, "..", "scripts/cyrus/smoke-readonly.sh"), "utf8");
    const block = s.slice(s.indexOf("if want storage"), s.indexOf('echo "== done'));
    assert.doesNotMatch(block, /\b(insert|update|delete)\s+(into|from)?\s*\\?"|systemctl (start|stop|restart|enable)|writeStored/i, "no writes, no service changes");
  });
});
